CREATE OR REPLACE FUNCTION public.add_laptop_to_purchase_batch(p_batch_id bigint, p_laptop jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b purchase_batches%ROWTYPE; l laptops%ROWTYPE; cached jsonb;
  extra_vnd numeric:=400000; divisor numeric:=1000000; import_price numeric;
BEGIN
  SELECT result INTO cached FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='ADD_LAPTOP_TO_PURCHASE_BATCH';
  IF FOUND THEN RETURN cached; END IF;
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN
    RAISE EXCEPTION 'Mã chống gửi trùng không hợp lệ'; END IF;
  SELECT * INTO b FROM purchase_batches WHERE id=p_batch_id AND active IS TRUE FOR SHARE;
  IF NOT FOUND OR b.status IN('CLOSED','CANCELLED') THEN
    RAISE EXCEPTION 'Lô mua không tồn tại hoặc đã đóng'; END IF;
  IF length(btrim(coalesce(p_laptop->>'name',''))) NOT BETWEEN 1 AND 240
    OR NOT EXISTS(SELECT 1 FROM app_options o WHERE o.group_key='category'
      AND o.option_key=p_laptop->>'category' AND o.is_active IS TRUE)
    OR coalesce(nullif(p_laptop->>'purchase_price_rmb','')::numeric,-1)<0
    OR coalesce(nullif(p_laptop->>'shipping_rmb','')::numeric,0)<0 THEN
    RAISE EXCEPTION 'Thông tin máy không hợp lệ'; END IF;
  SELECT coalesce(nullif(value->>'shippingVnd','')::numeric,400000),
         coalesce(nullif(value->>'divisor','')::numeric,1000000)
    INTO extra_vnd,divisor FROM app_settings WHERE key='formula';
  extra_vnd:=coalesce(extra_vnd,400000);
  divisor:=coalesce(divisor,1000000);
  import_price:=coalesce(nullif(p_laptop->>'import_price_vnd','')::numeric,
    round(((p_laptop->>'purchase_price_rmb')::numeric+
      coalesce(nullif(p_laptop->>'shipping_rmb','')::numeric,0))*b.exchange_rate+extra_vnd,2)/divisor);
  IF import_price<0 THEN RAISE EXCEPTION 'Giá nhập VNĐ không hợp lệ'; END IF;
  INSERT INTO laptops(name,category,serial,tracking_code_cn,tracking_code,
    purchase_price_rmb,price_rmb,shipping_rmb,purchase_exchange_rate,exchange_rate,
    import_price_vnd,purchase_batch_id,source_type,source_reference_id,status,location,
    charger_status,is_active,condition_note,created_by,import_date,month_key)
  VALUES(btrim(p_laptop->>'name'),p_laptop->>'category',
    nullif(left(btrim(coalesce(p_laptop->>'serial','')),100),''),
    left(btrim(coalesce(p_laptop->>'tracking_code_cn','')),200),
    nullif(left(btrim(coalesce(p_laptop->>'tracking_code_cn','')),200),''),
    (p_laptop->>'purchase_price_rmb')::numeric,(p_laptop->>'purchase_price_rmb')::numeric,
    coalesce(nullif(p_laptop->>'shipping_rmb','')::numeric,0),b.exchange_rate,b.exchange_rate,
    import_price,b.id,'SUPPLIER_PURCHASE',b.id::text,'in_transit','wh_cn','unchecked',true,
    left(coalesce(p_laptop->>'notes',''),2000),p_actor,b.purchase_date,to_char(b.purchase_date,'MM/YYYY'))
  RETURNING * INTO l;
  cached:=to_jsonb(l);
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'ADD_LAPTOP_TO_PURCHASE_BATCH',cached,p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('LAPTOP',l.id::text,'CREATE',jsonb_build_object(
    'event','LAPTOP_ADDED_TO_BATCH','purchase_batch_id',b.id,'batch_code',b.batch_code),p_actor);
  RETURN cached;
END;
$function$

CREATE OR REPLACE FUNCTION public.add_manual_laptop_cost(p_laptop_id bigint, p_cost_type text, p_amount_vnd numeric, p_description text, p_occurred_at timestamp with time zone, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE c laptop_cost_components%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM laptops WHERE id=p_laptop_id) THEN RAISE EXCEPTION 'Không tìm thấy laptop';END IF;
 IF p_cost_type NOT IN('RAM_UPGRADE','SSD_UPGRADE','ACCESSORY','CLEANING','OTHER') OR p_amount_vnd<=0 OR p_amount_vnd<>round(p_amount_vnd,0) OR btrim(coalesce(p_description,''))='' OR length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'Chi phí thủ công không hợp lệ';END IF;
 SELECT * INTO c FROM laptop_cost_components WHERE laptop_id=p_laptop_id AND source_type='MANUAL' AND source_id=p_idempotency_key AND cost_type=p_cost_type AND voided_at IS NULL;IF FOUND THEN RETURN to_jsonb(c);END IF;
 INSERT INTO laptop_cost_components(laptop_id,cost_type,amount_vnd,source_type,source_id,description,occurred_at,created_by) VALUES(p_laptop_id,p_cost_type,p_amount_vnd,'MANUAL',p_idempotency_key,left(p_description,1000),coalesce(p_occurred_at,timezone('utc',now())),p_actor) RETURNING * INTO c;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('LAPTOP_COST',c.id::text,'CREATE',jsonb_build_object('event','COST_COMPONENT_ADDED','laptop_id',p_laptop_id,'cost_type',p_cost_type,'amount_vnd',p_amount_vnd),p_actor);RETURN to_jsonb(c);
END $function$

CREATE OR REPLACE FUNCTION public.allocate_order_laptop(p_order_id bigint, p_laptop_id bigint, p_expected_owner bigint DEFAULT NULL::bigint, p_actor text DEFAULT 'SYSTEM'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE target orders; owner orders; machine laptops; previous_id bigint;
BEGIN
 -- Serialize allocation operations, including transfers of different machines.
 PERFORM pg_advisory_xact_lock(726481321);
 SELECT * INTO target FROM orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND OR target.is_active IS NOT TRUE OR target.order_status IN ('prepared','shipping','done','cancelled','returned') OR target.payment_status='refunded' THEN
   RAISE EXCEPTION 'Đơn không thể phân hoặc đổi máy';
 END IF;
 previous_id:=target.laptop_id;
 IF p_laptop_id IS NOT NULL THEN
   PERFORM pg_advisory_xact_lock(p_laptop_id);
   SELECT * INTO machine FROM laptops WHERE id=p_laptop_id FOR UPDATE;
   IF NOT FOUND OR machine.is_active IS NOT TRUE OR machine.status NOT IN ('available','reserved') THEN RAISE EXCEPTION 'Máy chưa sẵn sàng'; END IF;
   SELECT * INTO owner FROM orders WHERE laptop_id=p_laptop_id AND id<>target.id
     AND order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at) FOR UPDATE;
   IF owner.id IS DISTINCT FROM p_expected_owner THEN RAISE EXCEPTION 'Đơn giữ máy đã thay đổi. Vui lòng tải lại'; END IF;
   IF owner.id IS NOT NULL THEN
     IF owner.order_status IN ('prepared','shipping','done') THEN RAISE EXCEPTION 'Không thể chuyển máy đã chuẩn bị giao'; END IF;
     UPDATE orders SET laptop_id=NULL,laptop_locked=false,profit_vnd=0 WHERE id=owner.id;
   END IF;
 END IF;
 UPDATE orders SET laptop_id=p_laptop_id,laptop_locked=(p_laptop_id IS NOT NULL),reservation_expires_at=NULL WHERE id=target.id;
 PERFORM refresh_laptop_inventory(previous_id);
 IF p_laptop_id IS DISTINCT FROM previous_id THEN PERFORM refresh_laptop_inventory(p_laptop_id); END IF;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
 VALUES('ORDER',target.id::text,'UPDATE',jsonb_build_object('event','LAPTOP_ALLOCATION','previous_laptop_id',previous_id,'laptop_id',p_laptop_id,'previous_order_id',owner.id),p_actor);
 IF owner.id IS NOT NULL THEN
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
 VALUES('ORDER',owner.id::text,'UPDATE',jsonb_build_object('event','LAPTOP_TRANSFERRED','laptop_id',p_laptop_id,'target_order_id',target.id),p_actor);
 END IF;
 RETURN jsonb_build_object('order_id',target.id,'laptop_id',p_laptop_id);
END $function$

CREATE OR REPLACE FUNCTION public.cancel_repair_job(p_id uuid, p_reason text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j repair_jobs%ROWTYPE;
BEGIN
 SELECT * INTO j FROM repair_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR j.status IN('COMPLETED','CANCELLED') OR btrim(coalesce(p_reason,''))='' THEN
   RAISE EXCEPTION 'Không thể hủy phiếu sửa';
 END IF;
 UPDATE repair_jobs SET status='CANCELLED',resolution=left('Hủy: '||btrim(p_reason),5000),completed_at=timezone('utc',now())
 WHERE id=p_id RETURNING * INTO j;
 PERFORM set_config('app.laptop_transition','on',true);
 UPDATE laptops SET status='waiting_qc',available_for_sale_at=NULL WHERE id=j.laptop_id;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
 VALUES('REPAIR_JOB',j.id::text,'UPDATE',jsonb_build_object('event','REPAIR_CANCELLED','status','CANCELLED','reason',left(p_reason,1000)),p_actor);
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION public.cancel_reservation(p_id uuid, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r reservations%ROWTYPE;
BEGIN
 SELECT * INTO r FROM reservations WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy reservation'; END IF;
 IF r.status='CANCELLED' THEN RETURN to_jsonb(r); END IF;
 IF r.status<>'ACTIVE' THEN RAISE EXCEPTION 'Chỉ reservation ACTIVE được hủy'; END IF;
 UPDATE reservations SET status='CANCELLED',cancelled_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE id=r.id RETURNING * INTO r;
 IF NOT EXISTS(SELECT 1 FROM reservations WHERE laptop_id=r.laptop_id AND status='ACTIVE' AND expires_at>timezone('utc',now())) THEN
  PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='available' WHERE id=r.laptop_id AND status='reserved';
 END IF;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('RESERVATION',r.id::text,'UPDATE',jsonb_build_object('event','RESERVATION_CANCELLED','idempotency_key',p_idempotency_key),p_actor);
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION public.complete_qc_with_details(p_inspection_id uuid, p_disposition text, p_notes text, p_actor text, p_idempotency_key text, p_details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  q qc_inspections%ROWTYPE;
  result jsonb;
  shared_note text:=left(coalesce(p_notes,''),2000);
BEGIN
  SELECT * INTO q FROM qc_inspections WHERE id=p_inspection_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiên QC'; END IF;
  IF q.status='COMPLETED' AND q.completion_idempotency_key=p_idempotency_key
     AND q.disposition=p_disposition THEN
    RETURN to_jsonb(q);
  END IF;
  IF q.status<>'IN_PROGRESS' THEN RAISE EXCEPTION 'Phiên QC đã kết thúc'; END IF;

  UPDATE laptops
  SET qc_details=coalesce(p_details,'{}'::jsonb), condition_note=shared_note
  WHERE id=q.laptop_id;


  result:=complete_quick_qc(
    p_inspection_id,p_disposition,shared_note,p_actor,p_idempotency_key
  );
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_quick_qc(p_inspection_id uuid, p_disposition text, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE q qc_inspections%ROWTYPE; l laptops%ROWTYPE; linked jsonb; target text;
BEGIN
  IF coalesce(p_disposition,'') NOT IN ('PASS','FAIL','REPAIR','RETURN_CN')
    OR length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN
    RAISE EXCEPTION 'Kết quả QC không hợp lệ';
  END IF;
  SELECT * INTO q FROM qc_inspections WHERE id=p_inspection_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiên QC'; END IF;
  IF q.status='COMPLETED' AND q.completion_idempotency_key=p_idempotency_key
    AND q.disposition=p_disposition THEN RETURN to_jsonb(q); END IF;
  IF q.status<>'IN_PROGRESS' THEN RAISE EXCEPTION 'Phiên QC đã kết thúc'; END IF;
  SELECT * INTO l FROM laptops WHERE id=q.laptop_id AND is_active IS TRUE FOR UPDATE;
  IF NOT FOUND OR l.status<>'waiting_qc' THEN RAISE EXCEPTION 'Máy không còn ở trạng thái chờ QC'; END IF;
  IF EXISTS(SELECT 1 FROM repair_jobs WHERE laptop_id=l.id AND status NOT IN ('COMPLETED','CANCELLED'))
    OR EXISTS(SELECT 1 FROM supplier_return_items WHERE laptop_id=l.id AND status NOT IN ('REFUNDED','REPLACED','REJECTED','CANCELLED')) THEN
    RAISE EXCEPTION 'Máy còn phiếu sửa hoặc trả nhà cung cấp đang xử lý';
  END IF;
  IF p_disposition='RETURN_CN' AND (l.purchase_batch_id IS NULL OR l.source_type='UNKNOWN') THEN
    RAISE EXCEPTION 'Cần đối chiếu nhà cung cấp và lô mua trước khi BACK về TQ';
  END IF;
  UPDATE qc_inspections SET status='COMPLETED',
    result=CASE WHEN p_disposition='PASS' THEN 'PASS' ELSE 'FAIL' END,
    disposition=p_disposition, overall_notes='',
    completed_by=p_actor,completed_at=now(),completion_idempotency_key=p_idempotency_key
  WHERE id=q.id RETURNING * INTO q;
  target:=CASE p_disposition WHEN 'PASS' THEN 'available' WHEN 'REPAIR' THEN 'repair'
    WHEN 'RETURN_CN' THEN 'supplier_return' ELSE 'waiting_qc' END;
  IF p_disposition='REPAIR' THEN
    linked:=start_repair_job(jsonb_build_object('laptop_id',l.id,'source_type','QC','source_id',q.id,
      'reported_issue',coalesce(nullif(btrim(p_notes),''),'QC: Cần sửa chữa')),
      p_actor,'qc-repair-'||q.id::text);
  ELSIF p_disposition='RETURN_CN' THEN
    linked:=create_supplier_return(jsonb_build_object('reason','OTHER','reason_notes',coalesce(p_notes,'')),
      jsonb_build_array(jsonb_build_object('laptop_id',l.id,'qc_inspection_id',q.id,
        'reason','OTHER','condition_notes',coalesce(p_notes,''))),p_actor,'qc-return-'||q.id::text);
  ELSE
    PERFORM set_config('app.laptop_transition','on',true);
    UPDATE laptops SET status=target,
      available_for_sale_at=CASE WHEN p_disposition='PASS' THEN now() ELSE NULL END
    WHERE id=l.id;
  END IF;
  INSERT INTO stock_movements(laptop_id,movement_type,reference_type,reference_id,note,performed_by)
  VALUES(l.id,'QC_'||p_disposition,'QC_INSPECTION',q.id::text,coalesce(p_notes,''),p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('QC_INSPECTION',q.id::text,'UPDATE',jsonb_build_object('disposition',p_disposition,
    'laptop_id',l.id,'status',target,'linked_record',linked),p_actor);
  RETURN to_jsonb(q);
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_repair_job(p_id uuid, p_resolution text, p_outcome text, p_recommended_action text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j repair_jobs%ROWTYPE;
BEGIN
 SELECT * INTO j FROM repair_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu sửa'; END IF;
 IF j.status='COMPLETED' AND j.completion_idempotency_key=p_idempotency_key THEN RETURN to_jsonb(j); END IF;
 IF j.status<>'TESTING' OR btrim(coalesce(p_resolution,''))='' OR length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'Chỉ có thể hoàn tất phiếu đang TESTING'; END IF;
 IF p_outcome NOT IN('REPAIRED','NOT_REPAIRED','PARTIALLY_REPAIRED','NO_FAULT_FOUND') OR p_recommended_action NOT IN('RE_QC','SUPPLIER_RETURN','NO_FURTHER_ACTION','OTHER') THEN RAISE EXCEPTION 'Kết quả sửa chữa không hợp lệ'; END IF;
 UPDATE repair_jobs SET status='COMPLETED',resolution=left(p_resolution,5000),outcome=p_outcome,recommended_action=p_recommended_action,
  completed_at=timezone('utc',now()),completion_idempotency_key=p_idempotency_key,
  parts_cost_vnd=(SELECT coalesce(sum(total_cost_vnd),0) FROM repair_parts WHERE repair_job_id=p_id)
 WHERE id=p_id RETURNING * INTO j;
 PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='waiting_qc',available_for_sale_at=NULL WHERE id=j.laptop_id;
 PERFORM sync_laptop_cost_components(j.laptop_id,p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'UPDATE',jsonb_build_object('status','COMPLETED','outcome',p_outcome,'recommended_action',p_recommended_action),p_actor);
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION public.complete_trade_in_inspection(p_id uuid, p_mainboard_status text, p_findings text, p_checks jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE i trade_in_inspections%ROWTYPE;entry jsonb;
BEGIN
 SELECT * INTO i FROM trade_in_inspections WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy inspection';END IF;
 IF i.status='COMPLETED' THEN RETURN to_jsonb(i);END IF;
 IF p_mainboard_status NOT IN('ORIGINAL','OFFICIAL_REPLACED','REPAIRED','UNKNOWN') OR jsonb_typeof(coalesce(p_checks,'[]'::jsonb))<>'array' OR jsonb_array_length(coalesce(p_checks,'[]'::jsonb))=0 THEN RAISE EXCEPTION 'Kết quả inspection không hợp lệ';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_checks) LOOP
  IF entry->>'result' NOT IN('PASS','FAIL','WARNING','NOT_TESTED') OR btrim(coalesce(entry->>'check_key',''))='' THEN RAISE EXCEPTION 'Checklist không hợp lệ';END IF;
  INSERT INTO trade_in_check_items(inspection_id,check_key,result,notes) VALUES(i.id,upper(left(entry->>'check_key',60)),entry->>'result',left(coalesce(entry->>'notes',''),1000));
 END LOOP;
 UPDATE trade_in_inspections SET status='COMPLETED',mainboard_status=p_mainboard_status,findings=left(coalesce(p_findings,''),5000),completed_at=timezone('utc',now()) WHERE id=i.id RETURNING * INTO i;
 UPDATE trade_ins SET status='QUOTED',updated_at=timezone('utc',now()) WHERE id=i.trade_in_id;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN_INSPECTION',i.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_INSPECTION_COMPLETED','idempotency_key',p_idempotency_key),p_actor);
 RETURN to_jsonb(i);
END $function$

CREATE OR REPLACE FUNCTION public.convert_reservation_to_order(p_id uuid, p_order_id bigint, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r reservations%ROWTYPE; o orders%ROWTYPE; l laptops%ROWTYPE;
BEGIN
 SELECT * INTO r FROM reservations WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy reservation'; END IF;
 IF r.status='CONVERTED' THEN RETURN to_jsonb(r); END IF;
 SELECT * INTO l FROM laptops WHERE id=r.laptop_id FOR UPDATE;
 IF r.status<>'ACTIVE' OR r.expires_at<=timezone('utc',now()) OR l.status<>'reserved' THEN RAISE EXCEPTION 'Reservation không còn hiệu lực'; END IF;
 SELECT * INTO o FROM orders WHERE id=coalesce(p_order_id,r.order_id) AND is_active FOR UPDATE;
 IF NOT FOUND OR o.order_status IN('cancelled','returned','prepared','shipping','done') THEN RAISE EXCEPTION 'Cần draft order hợp lệ để chuyển đổi'; END IF;
 PERFORM set_config('app.reservation_conversion','on',true);
 UPDATE orders SET laptop_id=r.laptop_id,requested_laptop_id=r.laptop_id,reservation_expires_at=r.expires_at,updated_at=timezone('utc',now()) WHERE id=o.id;
 UPDATE reservations SET status='CONVERTED',order_id=o.id,converted_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE id=r.id RETURNING * INTO r;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('RESERVATION',r.id::text,'UPDATE',jsonb_build_object('event','RESERVATION_CONVERTED','order_id',o.id,'idempotency_key',p_idempotency_key),p_actor);
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION public.convert_trade_in_to_inventory(p_id uuid, p_data jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE t trade_ins%ROWTYPE; l laptops%ROWTYPE;
BEGIN
 SELECT * INTO t FROM trade_ins WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy trade-in'; END IF;
 IF t.inventory_laptop_id IS NOT NULL THEN SELECT * INTO l FROM laptops WHERE id=t.inventory_laptop_id; RETURN to_jsonb(l); END IF;
 IF t.status<>'RECEIVED' OR t.agreed_value_vnd<=0 THEN RAISE EXCEPTION 'Trade-in chưa được nhận hợp lệ'; END IF;
 INSERT INTO laptops(serial,name,category,status,location,is_active,source_type,source_reference_id,received_at,warehouse_date,created_by)
 VALUES(coalesce(nullif(t.serial,''),'TI-'||left(t.id::text,8)),concat_ws(' ',t.brand,t.model),
  coalesce(p_data->>'category','TRADE_IN'),'waiting_qc',coalesce(p_data->>'location','store'),true,'TRADE_IN',t.id::text,timezone('utc',now()),current_date,p_actor) RETURNING * INTO l;
 INSERT INTO laptop_cost_components(laptop_id,cost_type,amount_vnd,source_type,source_id,description,created_by)
 VALUES(l.id,'TRADE_IN_ACQUISITION',t.agreed_value_vnd,'TRADE_IN',t.id::text,'Thu cũ đổi mới '||t.trade_in_code,p_actor);
 UPDATE trade_ins SET status='CONVERTED_TO_INVENTORY',inventory_laptop_id=l.id,updated_at=timezone('utc',now()) WHERE id=t.id;
 RETURN to_jsonb(l);
END $function$

CREATE OR REPLACE FUNCTION public.create_cash_account(p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE a cash_accounts%ROWTYPE;
BEGIN IF coalesce((p_data->>'opening_balance')::numeric,0)<0 OR (p_data->>'account_type') NOT IN('CASH','BANK','WECHAT','ALIPAY','OTHER') OR (p_data->>'currency') NOT IN('VND','CNY') THEN RAISE EXCEPTION 'Thông tin tài khoản không hợp lệ';END IF;
 INSERT INTO cash_accounts(code,name,account_type,currency,opening_balance,opening_balance_at,created_by) VALUES(upper(btrim(p_data->>'code')),btrim(p_data->>'name'),p_data->>'account_type',p_data->>'currency',coalesce((p_data->>'opening_balance')::numeric,0),(p_data->>'opening_balance_at')::timestamptz,p_actor) RETURNING * INTO a;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('CASH_ACCOUNT',a.id::text,'CREATE',jsonb_build_object('event','CASH_ACCOUNT_CREATED','code',a.code,'currency',a.currency,'opening_balance',a.opening_balance),p_actor);RETURN to_jsonb(a);END $function$

CREATE OR REPLACE FUNCTION public.create_cod_receivable(p_order_id bigint, p_carrier text, p_tracking text, p_expected_settlement_at timestamp with time zone, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE o orders%ROWTYPE;c cod_receivables%ROWTYPE;expected numeric;
BEGIN SELECT * INTO c FROM cod_receivables WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(c);END IF;SELECT * INTO o FROM orders WHERE id=p_order_id AND is_active FOR UPDATE;IF NOT FOUND OR coalesce(o.cod_amount,0)<=0 THEN RAISE EXCEPTION 'Đơn hàng không có COD hợp lệ';END IF;expected:=round(least(o.cod_amount,o.debt_amount)*1000000,0);IF expected<=0 THEN RAISE EXCEPTION 'Đơn hàng không còn khoản COD phải thu';END IF;
 INSERT INTO cod_receivables(order_id,carrier,tracking_number,expected_cod_amount_vnd,shipped_at,expected_settlement_at,notes,idempotency_key,created_by) VALUES(o.id,left(coalesce(p_carrier,''),160),left(coalesce(p_tracking,o.tracking_code,''),200),expected,CASE WHEN o.order_status IN('shipping','done') THEN now() END,p_expected_settlement_at,left(coalesce(p_notes,''),2000),p_idempotency_key,p_actor) RETURNING * INTO c;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('COD_RECEIVABLE',c.id::text,'CREATE',jsonb_build_object('event','COD_CREATED','order_id',o.id,'expected_vnd',expected),p_actor);RETURN to_jsonb(c);END $function$

CREATE OR REPLACE FUNCTION public.create_order_before_invoice(p_order jsonb, p_recorded_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_input orders%ROWTYPE;
  v_order orders%ROWTYPE;
  v_laptop laptops%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_initial_deposit NUMERIC;
  v_initial_balance NUMERIC;
  v_created_payments JSONB := '[]'::jsonb;
BEGIN
  IF p_order IS NULL THEN RAISE EXCEPTION 'Order data is required'; END IF;
  v_input := jsonb_populate_record(NULL::orders, p_order);
  v_input.created_at := COALESCE(v_input.created_at, timezone('utc'::text, now()));
  v_input.updated_at := COALESCE(v_input.updated_at, timezone('utc'::text, now()));
  v_input := public.normalize_order_financials(v_input);
  IF v_input.month_key IS NULL OR btrim(v_input.month_key) = '' THEN
    v_input.month_key := TO_CHAR(CURRENT_DATE, 'MM/YYYY');
  END IF;

  INSERT INTO orders (
    created_date, sale_online, sale_offline, note, order_type, order_status,
    payment_status, payment_method, delivery_status, shipping_method, laptop_id,
    sale_price, deposit_amount, deposit_note, cod_amount, amount_paid, debt_amount,
    credit_card_fee, profit_vnd, trade_in_laptop_id, customer_id, customer_info,
    customer_address, tracking_code, ship_date, setup_note, warranty,
    laptop_locked, reservation_expires_at, cancel_reason, cancelled_at,
    returned_at, return_reason, is_active, month_key, created_at, updated_at
  ) VALUES (
    v_input.created_date, v_input.sale_online, v_input.sale_offline, v_input.note,
    v_input.order_type, v_input.order_status, v_input.payment_status,
    v_input.payment_method, v_input.delivery_status, v_input.shipping_method,
    v_input.laptop_id, v_input.sale_price, v_input.deposit_amount, v_input.deposit_note,
    v_input.cod_amount, v_input.amount_paid, v_input.debt_amount, v_input.credit_card_fee,
    v_input.profit_vnd, v_input.trade_in_laptop_id, v_input.customer_id,
    v_input.customer_info, v_input.customer_address, v_input.tracking_code,
    v_input.ship_date, v_input.setup_note, v_input.warranty, v_input.laptop_locked,
    v_input.reservation_expires_at, v_input.cancel_reason, v_input.cancelled_at,
    v_input.returned_at, v_input.return_reason, v_input.is_active, v_input.month_key,
    v_input.created_at, v_input.updated_at
  ) RETURNING * INTO v_order;

  v_initial_deposit := LEAST(COALESCE(v_order.deposit_amount, 0), COALESCE(v_order.amount_paid, 0));
  v_initial_balance := GREATEST(COALESCE(v_order.amount_paid, 0) - v_initial_deposit, 0);
  IF v_initial_deposit > 0 THEN
    INSERT INTO payments(order_id,payment_type,amount,payment_method,payment_date,note,recorded_by)
    VALUES(v_order.id,'deposit',v_initial_deposit,COALESCE(NULLIF(btrim(v_order.payment_method),''),'transfer_cash'),COALESCE(v_order.created_date,CURRENT_DATE),v_order.deposit_note,p_recorded_by)
    RETURNING * INTO v_payment;
    v_created_payments := v_created_payments || jsonb_build_array(to_jsonb(v_payment));
    INSERT INTO financial_records(record_type,category,amount,order_id,payment_id,occurred_on,payment_method,note,recorded_by)
    VALUES('income','deposit',v_initial_deposit,v_order.id,v_payment.id,COALESCE(v_order.created_date,CURRENT_DATE),COALESCE(NULLIF(btrim(v_order.payment_method),''),'transfer_cash'),v_order.deposit_note,p_recorded_by);
  END IF;
  IF v_initial_balance > 0 THEN
    INSERT INTO payments(order_id,payment_type,amount,payment_method,payment_date,note,recorded_by)
    VALUES(v_order.id,CASE WHEN v_order.payment_status='cod' THEN 'cod' ELSE 'balance' END,v_initial_balance,COALESCE(NULLIF(btrim(v_order.payment_method),''),'transfer_cash'),COALESCE(v_order.created_date,CURRENT_DATE),'Initial payment recorded with order',p_recorded_by)
    RETURNING * INTO v_payment;
    v_created_payments := v_created_payments || jsonb_build_array(to_jsonb(v_payment));
    INSERT INTO financial_records(record_type,category,amount,order_id,payment_id,occurred_on,payment_method,note,recorded_by)
    VALUES('income',CASE WHEN v_order.payment_status='cod' THEN 'cod' ELSE 'balance' END,v_initial_balance,v_order.id,v_payment.id,COALESCE(v_order.created_date,CURRENT_DATE),COALESCE(NULLIF(btrim(v_order.payment_method),''),'transfer_cash'),'Initial payment recorded with order',p_recorded_by);
  END IF;
  IF v_order.laptop_id IS NOT NULL THEN
    v_laptop := public.refresh_laptop_inventory(v_order.laptop_id);
    IF v_order.laptop_locked IS TRUE THEN
      INSERT INTO stock_movements(laptop_id,order_id,movement_type,note,performed_by)
      VALUES(v_order.laptop_id,v_order.id,CASE WHEN v_order.order_status IN ('prepared','shipping','done') THEN 'SOLD' ELSE 'RESERVED' END,'Inventory updated by order transaction',p_recorded_by);
    END IF;
  END IF;
  RETURN jsonb_build_object('order',to_jsonb(v_order),'laptop',CASE WHEN v_laptop.id IS NULL THEN NULL ELSE to_jsonb(v_laptop) END,'payments',v_created_payments,'inventory_applied',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_batch(p_batch jsonb, p_laptops jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  b purchase_batches%ROWTYPE;
  entry jsonb;
  created_rows jsonb;
  rate numeric;
  extra_vnd numeric;
  divisor numeric;
  import_price numeric;
BEGIN
  SELECT result INTO created_rows FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='CREATE_PURCHASE_BATCH';
  IF FOUND THEN RETURN created_rows; END IF;

  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100
     OR jsonb_typeof(p_laptops) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_laptops) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Lô mua phải có từ 1 đến 200 máy';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM suppliers
    WHERE id=(p_batch->>'supplier_id')::uuid AND active
  ) THEN
    RAISE EXCEPTION 'Nhà cung cấp không tồn tại hoặc đã ngừng sử dụng';
  END IF;

  rate:=coalesce(nullif(p_batch->>'purchase_exchange_rate','')::numeric,
                 nullif(p_batch->>'exchange_rate','')::numeric);
  IF rate IS NULL OR rate<=0 THEN RAISE EXCEPTION 'Tỷ giá mua không hợp lệ'; END IF;
  SELECT coalesce(nullif(value->>'shippingVnd','')::numeric,400000),
         coalesce(nullif(value->>'divisor','')::numeric,1000000)
    INTO extra_vnd,divisor FROM app_settings WHERE key='formula';
  extra_vnd:=coalesce(extra_vnd,400000);
  divisor:=coalesce(divisor,1000000);

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_laptops) x WHERE
      length(btrim(coalesce(x->>'name',''))) NOT BETWEEN 1 AND 240
      OR NOT EXISTS (
        SELECT 1 FROM app_options o
        WHERE o.group_key='category' AND o.option_key=x->>'category' AND o.is_active IS TRUE
      )
      OR coalesce(nullif(x->>'purchase_price_rmb','')::numeric,-1)<0
      OR coalesce(nullif(x->>'shipping_rmb','')::numeric,0)<0
      OR coalesce(nullif(x->>'import_price_vnd','')::numeric,-1)<0
      OR length(coalesce(x->>'tracking_code_cn',''))>200
  ) THEN
    RAISE EXCEPTION 'Thông tin máy trong lô không hợp lệ';
  END IF;

  INSERT INTO purchase_batches(batch_code,supplier_id,purchase_date,currency,exchange_rate,
    subtotal_rmb,domestic_shipping_rmb,other_cost_rmb,destination,status,notes,active,
    created_by,updated_by,idempotency_key,procurement_flow)
  VALUES(next_purchase_batch_code((p_batch->>'purchase_date')::date),
    (p_batch->>'supplier_id')::uuid,(p_batch->>'purchase_date')::date,'CNY',rate,
    0,0,0,'OTHER','CONFIRMED',left(coalesce(p_batch->>'notes',''),3000),true,
    p_actor,p_actor,p_idempotency_key,'DIRECT')
  RETURNING * INTO b;

  FOR entry IN SELECT value FROM jsonb_array_elements(p_laptops) LOOP
    import_price:=coalesce(
      nullif(entry->>'import_price_vnd','')::numeric,
      round((
        (entry->>'purchase_price_rmb')::numeric
        + coalesce(nullif(entry->>'shipping_rmb','')::numeric,0)
      ) * rate + extra_vnd,2) / divisor
    );
    INSERT INTO laptops(name,category,serial,tracking_code_cn,purchase_price_rmb,shipping_rmb,
      purchase_exchange_rate,import_price_vnd,purchase_batch_id,source_type,status,location,
      charger_status,is_active,condition_note,created_by,import_date,month_key,price_rmb,
      exchange_rate,tracking_code)
    VALUES(btrim(entry->>'name'),entry->>'category',
      nullif(left(btrim(coalesce(entry->>'serial','')),100),''),
      left(btrim(coalesce(entry->>'tracking_code_cn','')),200),
      (entry->>'purchase_price_rmb')::numeric,
      coalesce(nullif(entry->>'shipping_rmb','')::numeric,0),rate,import_price,b.id,
      'SUPPLIER_PURCHASE','in_transit','wh_cn','unchecked',true,
      left(coalesce(entry->>'notes',''),2000),p_actor,b.purchase_date,
      to_char(b.purchase_date,'MM/YYYY'),(entry->>'purchase_price_rmb')::numeric,rate,
      left(btrim(coalesce(entry->>'tracking_code_cn','')),200));
  END LOOP;

  SELECT jsonb_build_object('batch',to_jsonb(b),
    'laptops',coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb))
  INTO created_rows FROM laptops l WHERE l.purchase_batch_id=b.id;
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'CREATE_PURCHASE_BATCH',created_rows,p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('PURCHASE_BATCH',b.id::text,'CREATE',
    jsonb_build_object('batch_code',b.batch_code,'laptop_count',jsonb_array_length(p_laptops)),p_actor);
  RETURN created_rows;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_reservation(p_laptop_id bigint, p_customer_id bigint, p_order_id bigint, p_expires_at timestamp with time zone, p_deposit_payment_id bigint, p_notes text, p_user_id uuid, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r reservations%ROWTYPE; l laptops%ROWTYPE;
BEGIN
 SELECT * INTO r FROM reservations WHERE idempotency_key=p_idempotency_key; IF FOUND THEN RETURN to_jsonb(r); END IF;
 PERFORM expire_reservations(p_actor); SELECT * INTO l FROM laptops WHERE id=p_laptop_id FOR UPDATE;
 IF NOT FOUND OR l.status<>'available' OR NOT l.is_active THEN RAISE EXCEPTION 'Laptop không đủ điều kiện giữ máy'; END IF;
 IF p_expires_at<=timezone('utc',now()) THEN RAISE EXCEPTION 'Thời hạn giữ máy không hợp lệ'; END IF;
 INSERT INTO reservations(reservation_code,laptop_id,customer_id,order_id,status,reserved_by,expires_at,deposit_payment_id,notes,idempotency_key,created_by)
 VALUES(next_salesops_code('RSV','public.reservations'::regclass,'reservation_code'),l.id,p_customer_id,p_order_id,'ACTIVE',p_user_id,p_expires_at,p_deposit_payment_id,left(coalesce(p_notes,''),2000),p_idempotency_key,p_actor) RETURNING * INTO r;
 PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='reserved' WHERE id=l.id;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('RESERVATION',r.id::text,'CREATE',jsonb_build_object('event','RESERVATION_CREATED','laptop_id',l.id),p_actor);
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION public.create_supplier_return(p_data jsonb, p_items jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r supplier_returns%ROWTYPE; entry jsonb; l laptops%ROWTYPE; derived_supplier uuid; item_supplier uuid;
BEGIN
 SELECT * INTO r FROM supplier_returns WHERE idempotency_key=p_idempotency_key; IF FOUND THEN RETURN to_jsonb(r); END IF;
 IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Yêu cầu tạo phiếu trả không hợp lệ'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  SELECT * INTO l FROM laptops WHERE id=(entry->>'laptop_id')::bigint AND is_active FOR UPDATE;
  IF NOT FOUND OR l.status NOT IN('waiting_qc','repair','available') OR l.purchase_batch_id IS NULL OR l.source_type='UNKNOWN' THEN RAISE EXCEPTION 'Laptop không đủ điều kiện trả nhà cung cấp'; END IF;
  IF EXISTS(SELECT 1 FROM repair_jobs WHERE laptop_id=l.id AND status NOT IN('COMPLETED','CANCELLED')) THEN RAISE EXCEPTION 'Laptop còn phiếu sửa đang hoạt động; hãy hoàn tất hoặc hủy phiếu sửa trước'; END IF;
  SELECT supplier_id INTO item_supplier FROM purchase_batches WHERE id=l.purchase_batch_id AND active IS TRUE;
  IF item_supplier IS NULL THEN RAISE EXCEPTION 'Không xác định được nhà cung cấp từ lô mua'; END IF;
  IF derived_supplier IS NULL THEN derived_supplier:=item_supplier; ELSIF derived_supplier IS DISTINCT FROM item_supplier THEN RAISE EXCEPTION 'Một phiếu trả chỉ được chứa máy của cùng nhà cung cấp'; END IF;
 END LOOP;
 INSERT INTO supplier_returns(return_code,supplier_id,reason,reason_notes,notes,created_by,idempotency_key)
 VALUES(next_supplier_return_code(),derived_supplier,p_data->>'reason',left(coalesce(p_data->>'reason_notes',''),3000),left(coalesce(p_data->>'notes',''),3000),p_actor,p_idempotency_key) RETURNING * INTO r;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  SELECT * INTO l FROM laptops WHERE id=(entry->>'laptop_id')::bigint FOR UPDATE;
  INSERT INTO supplier_return_items(supplier_return_id,laptop_id,repair_job_id,qc_inspection_id,reason,condition_notes,expected_refund_rmb,agreed_refund_rmb,previous_laptop_status)
  VALUES(r.id,l.id,nullif(entry->>'repair_job_id','')::uuid,nullif(entry->>'qc_inspection_id','')::uuid,entry->>'reason',left(coalesce(entry->>'condition_notes',''),3000),nullif(entry->>'expected_refund_rmb','')::numeric,nullif(entry->>'agreed_refund_rmb','')::numeric,l.status);
  PERFORM set_config('app.laptop_transition','on',true);
  UPDATE laptops SET status='supplier_return',available_for_sale_at=NULL WHERE id=l.id;
 END LOOP;
 INSERT INTO supplier_return_events(supplier_return_id,event_type,details,performed_by) VALUES(r.id,'CREATED',jsonb_build_object('item_count',jsonb_array_length(p_items),'supplier_derived',true),p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('SUPPLIER_RETURN',r.id::text,'CREATE',jsonb_build_object('event','SUPPLIER_RETURN_CREATED','supplier_id',derived_supplier,'item_count',jsonb_array_length(p_items)),p_actor);
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION public.enforce_order_customer_obligation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_trade_in_credit_million numeric := greatest(coalesce(NEW.trade_in_credit_vnd, 0), 0) / 1000000;
BEGIN
  NEW.sale_price := greatest(coalesce(NEW.sale_price, 0), 0);
  NEW.amount_paid := greatest(coalesce(NEW.amount_paid, 0), 0);
  IF NEW.amount_paid + v_trade_in_credit_million > NEW.sale_price + 0.000001 THEN
    RAISE EXCEPTION 'Tiền đã thu và credit thu cũ vượt giá bán';
  END IF;

  NEW.debt_amount := greatest(NEW.sale_price - NEW.amount_paid - v_trade_in_credit_million, 0);
  NEW.payment_status := CASE
    WHEN NEW.payment_status = 'refunded' THEN 'refunded'
    WHEN NEW.debt_amount = 0 AND NEW.sale_price > 0 THEN 'paid'
    WHEN NEW.payment_status = 'cod' THEN 'cod'
    WHEN NEW.amount_paid > 0 THEN 'deposited'
    ELSE 'unpaid'
  END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_warranty_case_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
BEGIN
  NEW.status := lower(trim(coalesce(NEW.status, '')));
  IF NEW.status NOT IN ('received', 'checking', 'wait_parts', 'repairing', 'done', 'swap_device', 'refunded') THEN
    RAISE EXCEPTION 'Trạng thái bảo hành không hợp lệ';
  END IF;
  IF NEW.laptop_id IS NULL THEN
    RAISE EXCEPTION 'Phiếu bảo hành phải gắn với laptop';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.laptop_id IS DISTINCT FROM OLD.laptop_id THEN
    RAISE EXCEPTION 'Không thể đổi máy gốc của phiếu bảo hành';
  END IF;

  IF NEW.order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM public.orders WHERE id = NEW.order_id;
    IF NOT FOUND OR (
      NEW.laptop_id IS DISTINCT FROM v_order.laptop_id
      AND NEW.laptop_id IS DISTINCT FROM v_order.requested_laptop_id
    ) THEN
      RAISE EXCEPTION 'Đơn gốc không thuộc máy đang tiếp nhận bảo hành';
    END IF;
  END IF;

  IF NEW.status IN ('done', 'swap_device', 'refunded') THEN
    NEW.resolved_date := coalesce(NEW.resolved_date, current_date);
  ELSE
    NEW.resolved_date := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.expire_reservations(p_actor text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n integer; laptop_key bigint;
BEGIN
 FOR laptop_key IN SELECT DISTINCT laptop_id FROM reservations WHERE status='ACTIVE' AND expires_at<=timezone('utc',now()) FOR UPDATE LOOP
  UPDATE reservations SET status='EXPIRED',expired_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE laptop_id=laptop_key AND status='ACTIVE' AND expires_at<=timezone('utc',now());
  IF NOT EXISTS(SELECT 1 FROM reservations WHERE laptop_id=laptop_key AND status='ACTIVE' AND expires_at>timezone('utc',now())) THEN
   PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='available' WHERE id=laptop_key AND status='reserved';
  END IF;
 END LOOP;
 GET DIAGNOSTICS n=ROW_COUNT;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.guard_closed_supplier_return_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE parent_status text;
BEGIN
 IF TG_TABLE_NAME='supplier_returns' THEN
  IF TG_OP='DELETE' OR OLD.status IN('CLOSED','CANCELLED') THEN RAISE EXCEPTION 'Lịch sử phiếu trả đã đóng là bất biến';END IF;
 ELSE
  SELECT status INTO parent_status FROM supplier_returns WHERE id=coalesce(NEW.supplier_return_id,OLD.supplier_return_id);
  IF (TG_OP='DELETE' OR parent_status IN('CLOSED','CANCELLED'))
     AND current_setting('app.supplier_return_transition',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Chi tiết phiếu trả đã đóng là bất biến';END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.guard_commission_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND OLD.status IN('APPROVED','PAID') THEN RAISE EXCEPTION 'Commission đã duyệt/chi không thể xóa';END IF;
 IF TG_OP='UPDATE' AND OLD.status IN('APPROVED','PAID') AND (NEW.amount_vnd IS DISTINCT FROM OLD.amount_vnd OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.beneficiary_type IS DISTINCT FROM OLD.beneficiary_type OR NEW.beneficiary_user_id IS DISTINCT FROM OLD.beneficiary_user_id OR NEW.beneficiary_name IS DISTINCT FROM OLD.beneficiary_name OR NEW.commission_type IS DISTINCT FROM OLD.commission_type OR NEW.calculation_basis IS DISTINCT FROM OLD.calculation_basis OR NEW.calculation_snapshot_json IS DISTINCT FROM OLD.calculation_snapshot_json) THEN RAISE EXCEPTION 'Commission đã duyệt là bất biến';END IF;
 IF TG_OP='UPDATE' AND OLD.status='PAID' AND NEW.status<>'PAID' THEN RAISE EXCEPTION 'Commission đã chi không thể đổi trạng thái';END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.guard_laptop_cost_component_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Lịch sử cấu phần giá vốn là bất biến';END IF;
 IF OLD.source_type<>'MANUAL' AND current_setting('app.cost_component_sync',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Cấu phần giá vốn hệ thống là bất biến';END IF;
 IF OLD.source_type<>'MANUAL' THEN RETURN NEW;END IF;
 IF current_setting('app.cost_component_void',true) IS DISTINCT FROM 'on' OR NEW.laptop_id IS DISTINCT FROM OLD.laptop_id OR NEW.cost_type IS DISTINCT FROM OLD.cost_type OR NEW.amount_vnd IS DISTINCT FROM OLD.amount_vnd OR NEW.source_type IS DISTINCT FROM OLD.source_type OR NEW.source_id IS DISTINCT FROM OLD.source_id OR NEW.description IS DISTINCT FROM OLD.description OR NEW.occurred_at IS DISTINCT FROM OLD.occurred_at OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN RAISE EXCEPTION 'Chi phí thủ công chỉ được void qua workflow giá vốn';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_order_sellable_laptop()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE candidate_id bigint; candidate_status text;
BEGIN
  candidate_id:=NEW.laptop_id;
  IF candidate_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND candidate_id=OLD.laptop_id
     AND NEW.laptop_id IS NOT DISTINCT FROM OLD.laptop_id
     AND NEW.requested_laptop_id IS NOT DISTINCT FROM OLD.requested_laptop_id THEN RETURN NEW; END IF;
  SELECT status INTO candidate_status FROM laptops WHERE id=candidate_id AND is_active IS TRUE FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laptop không tồn tại hoặc đã ngừng sử dụng'; END IF;
  IF candidate_status NOT IN('available','reserved') THEN
    RAISE EXCEPTION 'Laptop chưa sẵn sàng để bán (trạng thái: %)',candidate_status;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_trade_in_economic_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND OLD.status IN('ACCEPTED','RECEIVED','CONVERTED_TO_INVENTORY') THEN RAISE EXCEPTION 'Trade-in đã cam kết kinh tế không thể xóa';END IF;
 IF TG_OP='UPDATE' AND OLD.status='INSPECTING' AND NEW.status='ACCEPTED' THEN RAISE EXCEPTION 'Trade-in phải hoàn tất inspection trước khi chấp nhận';END IF;
 IF TG_OP='UPDATE' AND OLD.status IN('ACCEPTED','RECEIVED','CONVERTED_TO_INVENTORY')
    AND (NEW.agreed_value_vnd IS DISTINCT FROM OLD.agreed_value_vnd OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.inventory_laptop_id IS DISTINCT FROM OLD.inventory_laptop_id OR NEW.serial IS DISTINCT FROM OLD.serial) THEN
  IF NOT (OLD.status='RECEIVED' AND NEW.status='CONVERTED_TO_INVENTORY' AND OLD.inventory_laptop_id IS NULL AND NEW.inventory_laptop_id IS NOT NULL AND NEW.agreed_value_vnd=OLD.agreed_value_vnd AND NEW.order_id IS NOT DISTINCT FROM OLD.order_id AND NEW.serial IS NOT DISTINCT FROM OLD.serial) THEN RAISE EXCEPTION 'Nguồn kinh tế trade-in đã cam kết là bất biến';END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.ignore_incoming_laptop(p_laptop_id bigint, p_reason text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE;
BEGIN
  IF btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'Cần nhập lý do bỏ qua'; END IF;
  PERFORM set_config('app.laptop_transition','on',true);
  UPDATE laptops SET status='ignored',ignored_at=timezone('utc',now()),ignored_by=p_actor,
    ignore_reason=left(btrim(p_reason),1000),is_active=false
  WHERE id=p_laptop_id AND status='in_transit' RETURNING * INTO l;
  IF NOT FOUND THEN RAISE EXCEPTION 'Máy không còn ở trạng thái có thể bỏ qua'; END IF;
