CREATE OR REPLACE FUNCTION public.normalize_order_financials(p_order orders)
 RETURNS orders
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_order orders := p_order;
BEGIN
  v_order.is_active := COALESCE(v_order.is_active, true);
  v_order.sale_price := GREATEST(COALESCE(v_order.sale_price, 0), 0);
  v_order.deposit_amount := LEAST(v_order.sale_price, GREATEST(COALESCE(v_order.deposit_amount, 0), 0));
  v_order.amount_paid := LEAST(v_order.sale_price, GREATEST(COALESCE(v_order.amount_paid, 0), v_order.deposit_amount));
  v_order.debt_amount := GREATEST(v_order.sale_price - v_order.amount_paid, 0);
  v_order.cod_amount := LEAST(v_order.sale_price, GREATEST(COALESCE(v_order.cod_amount, 0), 0));
  v_order.credit_card_fee := GREATEST(COALESCE(v_order.credit_card_fee, 0), 0);
  v_order.profit_vnd := COALESCE(v_order.profit_vnd, 0);
  v_order.payment_status := lower(btrim(COALESCE(v_order.payment_status, '')));
  IF v_order.payment_status NOT IN ('unpaid','deposited','cod','paid','refunded') THEN v_order.payment_status := 'unpaid'; END IF;
  IF v_order.laptop_id IS NOT NULL AND v_order.is_active IS TRUE
     AND v_order.reservation_expires_at IS NULL
     AND (v_order.order_status='deposited' OR v_order.payment_status='deposited') THEN
    v_order.reservation_expires_at := timezone('utc'::text,now()) + interval '48 hours';
  END IF;
  v_order.laptop_locked := public.order_uses_laptop(v_order.laptop_id,v_order.is_active,v_order.order_status,v_order.payment_status,v_order.reservation_expires_at);
  RETURN v_order;
END $function$

CREATE OR REPLACE FUNCTION public.post_manual_account_transaction(p_account_id uuid, p_direction text, p_amount numeric, p_description text, p_occurred_at timestamp with time zone, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE a cash_accounts%ROWTYPE;t account_transactions%ROWTYPE;
BEGIN SELECT * INTO t FROM account_transactions WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(t);END IF;IF p_direction NOT IN('IN','OUT') OR p_amount<=0 OR btrim(coalesce(p_description,''))='' THEN RAISE EXCEPTION 'Giao dịch thủ công không hợp lệ';END IF;a:=assert_cash_account(p_account_id,(SELECT currency FROM cash_accounts WHERE id=p_account_id),p_occurred_at);
 INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,created_by) VALUES(a.id,p_direction,p_amount,a.currency,'MANUAL',p_idempotency_key,CASE WHEN p_direction='IN' THEN 'MANUAL_IN' ELSE 'MANUAL_OUT' END,p_occurred_at,left(p_description,1000),p_idempotency_key,p_actor) RETURNING * INTO t;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('ACCOUNT_TRANSACTION',t.id::text,'CREATE',jsonb_build_object('event','ACCOUNT_TRANSACTION_POSTED','account_id',a.id,'direction',p_direction,'amount',p_amount,'currency',a.currency),p_actor);RETURN to_jsonb(t);END $function$

CREATE OR REPLACE FUNCTION public.prevent_completed_qc_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE parent_status text;
BEGIN
  IF TG_TABLE_NAME='qc_inspections' THEN
    IF TG_OP='DELETE' OR OLD.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Lịch sử QC đã kết thúc là bất biến'; END IF;
  ELSE
    SELECT status INTO parent_status FROM qc_inspections WHERE id=coalesce(NEW.qc_inspection_id,OLD.qc_inspection_id);
    IF TG_OP='DELETE' OR parent_status<>'IN_PROGRESS' THEN RAISE EXCEPTION 'Checklist của phiên QC đã kết thúc là bất biến'; END IF;
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.prevent_laptop_double_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.order_uses_laptop(
    NEW.laptop_id, NEW.is_active, NEW.order_status, NEW.payment_status, NEW.reservation_expires_at
  ) THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(NEW.laptop_id);
  IF EXISTS (
    SELECT 1
    FROM orders existing_order
    WHERE existing_order.laptop_id = NEW.laptop_id
      AND existing_order.id IS DISTINCT FROM NEW.id
      AND public.order_uses_laptop(
        existing_order.laptop_id,
        existing_order.is_active,
        existing_order.order_status,
        existing_order.payment_status,
        existing_order.reservation_expires_at
      )
  ) THEN
    RAISE EXCEPTION 'Laptop % is already reserved by another active order', NEW.laptop_id
      USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_inventory(p_expected jsonb, p_unknown jsonb, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE prior jsonb; known_result jsonb:=jsonb_build_object('laptops','[]'::jsonb,'received_count',0);
  entry jsonb; unknown_rows jsonb:='[]'::jsonb; unknown_row jsonb; index_no integer:=0;
BEGIN
  SELECT result INTO prior FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='RECEIVE_INVENTORY';
  IF FOUND THEN RETURN prior; END IF;
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 80
     OR jsonb_typeof(coalesce(p_expected,'[]'::jsonb)) IS DISTINCT FROM 'array'
     OR jsonb_typeof(coalesce(p_unknown,'[]'::jsonb)) IS DISTINCT FROM 'array'
     OR jsonb_array_length(coalesce(p_expected,'[]'::jsonb))+jsonb_array_length(coalesce(p_unknown,'[]'::jsonb)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Đợt nhận hàng không hợp lệ';
  END IF;
  IF jsonb_array_length(coalesce(p_expected,'[]'::jsonb))>0 THEN
    known_result:=receive_purchase_laptops(p_expected,p_notes,p_actor,p_idempotency_key||'-expected');
    -- Receiving edits the same laptop note instead of creating or appending another note.
    FOR entry IN SELECT value FROM jsonb_array_elements(p_expected) LOOP
      IF entry ? 'notes' THEN
        UPDATE laptops SET condition_note=left(coalesce(entry->>'notes',''),2000)
        WHERE id=(entry->>'laptop_id')::bigint;
      END IF;
    END LOOP;
    SELECT jsonb_build_object('laptops',coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb),
      'received_count',count(*)) INTO known_result
    FROM laptops l WHERE l.id IN (SELECT (value->>'laptop_id')::bigint FROM jsonb_array_elements(p_expected));
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(coalesce(p_unknown,'[]'::jsonb)) LOOP
    index_no:=index_no+1;
    unknown_row:=receive_unknown_laptop(entry,p_actor,p_idempotency_key||'-unknown-'||index_no::text);
    unknown_rows:=unknown_rows||jsonb_build_array(unknown_row);
  END LOOP;
  prior:=jsonb_build_object('expected',known_result->'laptops','unknown',unknown_rows,
    'received_count',jsonb_array_length(coalesce(known_result->'laptops','[]'::jsonb))+jsonb_array_length(unknown_rows));
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'RECEIVE_INVENTORY',prior,p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('RECEIVING',p_idempotency_key,'CREATE',jsonb_build_object('received_count',prior->'received_count','notes',left(coalesce(p_notes,''),1000)),p_actor);
  RETURN prior;
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_purchase_laptops(p_items jsonb, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE entry jsonb; l laptops%ROWTYPE; rows jsonb:='[]'::jsonb; prior jsonb;
BEGIN
  SELECT result INTO prior FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='RECEIVE_PURCHASE_LAPTOPS';
  IF FOUND THEN RETURN prior; END IF;
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100
     OR jsonb_typeof(p_items) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Đợt nhận hàng không hợp lệ';
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_items)) <>
     (SELECT count(DISTINCT (value->>'laptop_id')::bigint) FROM jsonb_array_elements(p_items)) THEN
    RAISE EXCEPTION 'Danh sách nhận hàng có máy bị trùng';
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    SELECT * INTO l FROM laptops WHERE id=(entry->>'laptop_id')::bigint FOR UPDATE;
    IF NOT FOUND OR l.source_type NOT IN('SUPPLIER_PURCHASE','SUPPLIER_REPLACEMENT') THEN
      RAISE EXCEPTION 'Máy không thuộc luồng mua từ nhà cung cấp';
    END IF;
    IF l.status<>'in_transit' THEN RAISE EXCEPTION 'Máy % không còn ở trạng thái chưa về hàng',l.id; END IF;
    PERFORM set_config('app.laptop_transition','on',true);
    UPDATE laptops SET
      status='waiting_qc',received_at=coalesce(nullif(entry->>'received_at','')::date,current_date)::timestamptz,
      warehouse_date=coalesce(nullif(entry->>'received_at','')::date,current_date),location='store',
      serial=coalesce(nullif(left(btrim(coalesce(entry->>'serial','')),100),''),serial),
      tracking_code_cn=coalesce(nullif(left(btrim(coalesce(entry->>'tracking_code_cn','')),200),''),tracking_code_cn),
      tracking_code=coalesce(nullif(left(btrim(coalesce(entry->>'tracking_code_cn','')),200),''),tracking_code),
      charger_status=coalesce(nullif(entry->>'charger_status',''),charger_status),
      condition_note=left(concat_ws(E'\n',nullif(condition_note,''),nullif(entry->>'notes',''),nullif(p_notes,'')),2000)
    WHERE id=l.id RETURNING * INTO l;
    INSERT INTO stock_movements(laptop_id,movement_type,from_location,to_location,note,performed_by,reference_type,reference_id)
    VALUES(l.id,'PURCHASE_RECEIVE','IN_TRANSIT',l.location,'Nhận hàng từ lô '||coalesce(l.purchase_batch_id::text,''),p_actor,'PURCHASE_BATCH',l.purchase_batch_id::text);
    rows:=rows||jsonb_build_array(to_jsonb(l));
  END LOOP;
  prior:=jsonb_build_object('laptops',rows,'received_count',jsonb_array_length(rows));
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'RECEIVE_PURCHASE_LAPTOPS',prior,p_actor);
  RETURN prior;
END $function$

CREATE OR REPLACE FUNCTION public.receive_unknown_laptop(p_data jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; prior jsonb;
BEGIN
  SELECT result INTO prior FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='RECEIVE_UNKNOWN_LAPTOP';
  IF FOUND THEN RETURN prior; END IF;
  IF length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 240 THEN RAISE EXCEPTION 'Tên máy không hợp lệ'; END IF;
  INSERT INTO laptops(name,serial,tracking_code_cn,tracking_code,source_type,status,
    location,charger_status,is_active,condition_note,received_at,warehouse_date,created_by)
  VALUES(btrim(p_data->>'name'),nullif(left(btrim(coalesce(p_data->>'serial','')),100),''),left(btrim(coalesce(p_data->>'tracking_code_cn','')),200),
    left(btrim(coalesce(p_data->>'tracking_code_cn','')),200),'UNKNOWN','waiting_qc','store',
    coalesce(nullif(p_data->>'charger_status',''),'unchecked'),true,left(coalesce(p_data->>'notes',''),2000),
    coalesce(nullif(p_data->>'received_at','')::date,current_date)::timestamptz,
    coalesce(nullif(p_data->>'received_at','')::date,current_date),p_actor) RETURNING * INTO l;
  prior:=to_jsonb(l);
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'RECEIVE_UNKNOWN_LAPTOP',prior,p_actor);
  INSERT INTO stock_movements(laptop_id,movement_type,to_location,note,performed_by,reference_type,reference_id)
  VALUES(l.id,'PURCHASE_RECEIVE',l.location,'Nhận máy chưa rõ nguồn',p_actor,'UNKNOWN_INTAKE',p_idempotency_key);
  RETURN prior;
END $function$

CREATE OR REPLACE FUNCTION public.reconcile_cash_account(p_account_id uuid, p_actual numeric, p_reconciled_at timestamp with time zone, p_notes text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a cash_accounts%ROWTYPE;recorded numeric(20,2);r account_reconciliations%ROWTYPE;
BEGIN
 SELECT * INTO a FROM cash_accounts WHERE id=p_account_id AND is_active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy tài khoản';END IF;
 IF p_actual IS NULL OR p_reconciled_at IS NULL THEN RAISE EXCEPTION 'Thông tin đối soát không hợp lệ';END IF;
 SELECT (a.opening_balance+coalesce(sum(CASE WHEN direction='IN' THEN amount ELSE -amount END),0))::numeric(20,2)
 INTO recorded FROM account_transactions WHERE account_id=a.id AND occurred_at>=a.opening_balance_at;
 INSERT INTO account_reconciliations(account_id,recorded_balance,actual_balance,reconciled_at,notes,created_by)
 VALUES(a.id,recorded,p_actual,p_reconciled_at,left(coalesce(p_notes,''),2000),p_actor) RETURNING * INTO r;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES
 ('CASH_ACCOUNT',a.id::text,'UPDATE',jsonb_build_object('event','ACCOUNT_RECONCILED','recorded',recorded,'actual',p_actual,'difference',r.difference),p_actor);
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION public.reconcile_unknown_laptop(p_unknown_laptop_id bigint, p_expected_laptop_id bigint, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE physical laptops%ROWTYPE; expected laptops%ROWTYPE; prior jsonb;
BEGIN
  SELECT result INTO prior FROM operation_requests
  WHERE idempotency_key=p_idempotency_key AND operation='RECONCILE_UNKNOWN_LAPTOP';
  IF FOUND THEN RETURN prior; END IF;
  IF p_unknown_laptop_id=p_expected_laptop_id THEN RAISE EXCEPTION 'Hai laptop phải khác nhau'; END IF;
  PERFORM pg_advisory_xact_lock(least(p_unknown_laptop_id,p_expected_laptop_id));
  PERFORM pg_advisory_xact_lock(greatest(p_unknown_laptop_id,p_expected_laptop_id));
  SELECT * INTO physical FROM laptops WHERE id=p_unknown_laptop_id FOR UPDATE;
  SELECT * INTO expected FROM laptops WHERE id=p_expected_laptop_id FOR UPDATE;
  IF physical.id IS NULL OR physical.source_type<>'UNKNOWN' OR physical.status<>'waiting_qc' THEN
    RAISE EXCEPTION 'Laptop thực nhận không còn là máy chưa rõ nguồn đang chờ QC';
  END IF;
  IF expected.id IS NULL OR expected.status<>'in_transit' OR expected.source_type NOT IN('SUPPLIER_PURCHASE','SUPPLIER_REPLACEMENT') THEN
    RAISE EXCEPTION 'Laptop dự kiến không còn nguyên trạng chưa về hàng';
  END IF;
  IF EXISTS(SELECT 1 FROM qc_inspections WHERE laptop_id=expected.id)
     OR EXISTS(SELECT 1 FROM repair_jobs WHERE laptop_id=expected.id)
     OR EXISTS(SELECT 1 FROM orders WHERE laptop_id=expected.id OR requested_laptop_id=expected.id)
     OR EXISTS(SELECT 1 FROM reservations WHERE laptop_id=expected.id)
     OR EXISTS(SELECT 1 FROM stock_movements WHERE laptop_id=expected.id) THEN
    RAISE EXCEPTION 'Laptop dự kiến đã có lịch sử nghiệp vụ, không thể gộp';
  END IF;
  -- Release unique serial/tracking keys held by the untouched placeholder before
  -- copying its source data onto the physical laptop that keeps the stable ID.
  DELETE FROM laptops WHERE id=expected.id;
  UPDATE laptops SET purchase_batch_id=expected.purchase_batch_id,source_type=expected.source_type,
    purchase_price_rmb=expected.purchase_price_rmb,shipping_rmb=expected.shipping_rmb,
    purchase_exchange_rate=expected.purchase_exchange_rate,price_rmb=expected.purchase_price_rmb,
    exchange_rate=expected.purchase_exchange_rate,tracking_code_cn=coalesce(nullif(expected.tracking_code_cn,''),tracking_code_cn),
    tracking_code=coalesce(nullif(expected.tracking_code_cn,''),tracking_code),
    name=coalesce(nullif(name,''),expected.name),
    serial=coalesce(serial,expected.serial),import_date=expected.import_date,month_key=expected.month_key,
    source_reference_id=expected.source_reference_id
  WHERE id=physical.id RETURNING * INTO physical;
  prior:=to_jsonb(physical);
  INSERT INTO operation_requests(idempotency_key,operation,result,created_by)
  VALUES(p_idempotency_key,'RECONCILE_UNKNOWN_LAPTOP',prior,p_actor);
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('LAPTOP',physical.id::text,'UPDATE',jsonb_build_object('event','UNKNOWN_SOURCE_RECONCILED','deleted_expected_laptop_id',expected.id,'purchase_batch_id',physical.purchase_batch_id),p_actor);
  RETURN prior;
END $function$

CREATE OR REPLACE FUNCTION public.record_cod_settlement(p_cod_id uuid, p_amount_vnd numeric, p_account_id uuid, p_reference text, p_settled_at timestamp with time zone, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c cod_receivables%ROWTYPE;
  s cod_settlements%ROWTYPE;
  a cash_accounts%ROWTYPE;
  paid numeric;
  remaining numeric;
  t account_transactions%ROWTYPE;
BEGIN
  SELECT * INTO s FROM cod_settlements WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN RETURN to_jsonb(s); END IF;

  SELECT * INTO c FROM cod_receivables WHERE id = p_cod_id FOR UPDATE;
  IF NOT FOUND OR c.status NOT IN ('WAITING_SETTLEMENT', 'PARTIALLY_SETTLED', 'DISPUTED') THEN
    RAISE EXCEPTION 'COD chưa ở trạng thái nhận đối soát';
  END IF;

  a := assert_cash_account(p_account_id, 'VND', p_settled_at);
  SELECT coalesce(sum(amount_vnd), 0) INTO paid FROM cod_settlements WHERE cod_receivable_id = c.id;
  remaining := c.expected_cod_amount_vnd - paid;
  IF p_amount_vnd <= 0 OR p_amount_vnd > remaining THEN
    RAISE EXCEPTION 'Số tiền COD vượt khoản còn phải thu';
  END IF;

  INSERT INTO cod_settlements(cod_receivable_id, amount_vnd, account_id, reference, settled_at, idempotency_key, created_by)
  VALUES(c.id, p_amount_vnd, a.id, left(coalesce(p_reference, ''), 300), p_settled_at, p_idempotency_key, p_actor)
  RETURNING * INTO s;

  INSERT INTO account_transactions(account_id, direction, amount, currency, reference_type, reference_id, transaction_type, occurred_at, description, idempotency_key, created_by)
  VALUES(a.id, 'IN', p_amount_vnd, 'VND', 'COD_SETTLEMENT', s.id::text, 'COD_SETTLEMENT', p_settled_at, 'COD order #' || c.order_id, p_idempotency_key || '-CASH', p_actor)
  RETURNING * INTO t;

  paid := paid + p_amount_vnd;
  UPDATE cod_receivables
  SET status = CASE WHEN paid = c.expected_cod_amount_vnd THEN 'SETTLED' ELSE 'PARTIALLY_SETTLED' END,
      settled_at = CASE WHEN paid = c.expected_cod_amount_vnd THEN p_settled_at END
  WHERE id = c.id;

  INSERT INTO activity_logs(entity_type, entity_id, action, changes, user_name)
  VALUES('COD_SETTLEMENT', s.id::text, 'CREATE', jsonb_build_object('event', CASE WHEN paid = c.expected_cod_amount_vnd THEN 'COD_SETTLED' ELSE 'COD_SETTLEMENT_RECORDED' END, 'cod_id', c.id, 'amount_vnd', p_amount_vnd, 'resolved_dispute', c.status = 'DISPUTED'), p_actor);
  RETURN to_jsonb(s);
END
$function$

CREATE OR REPLACE FUNCTION public.record_order_payment(p_order_id bigint, p_amount numeric, p_payment_type text, p_payment_method text DEFAULT 'transfer_cash'::text, p_payment_date date DEFAULT CURRENT_DATE, p_reference_code text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_recorded_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order orders%ROWTYPE;
  v_payment payments%ROWTYPE;
  v_financial financial_records%ROWTYPE;
  v_new_amount_paid NUMERIC;
  v_old_uses BOOLEAN;
  v_new_uses BOOLEAN;
  v_old_committed BOOLEAN;
  v_new_committed BOOLEAN;
  v_laptop laptops%ROWTYPE;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;
  IF p_payment_type NOT IN ('deposit', 'balance', 'cod', 'refund', 'other') THEN
    RAISE EXCEPTION 'Unsupported payment type';
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order % does not exist', p_order_id;
  END IF;
  IF v_order.is_active IS NOT TRUE THEN
    RAISE EXCEPTION 'Cannot record payment for an inactive order';
  END IF;

  v_old_uses := public.order_uses_laptop(
    v_order.laptop_id,
    v_order.is_active,
    v_order.order_status,
    v_order.payment_status,
    v_order.reservation_expires_at
  );
  v_old_committed := v_old_uses AND v_order.order_status IN ('prepared', 'shipping', 'done');
  IF v_order.laptop_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(v_order.laptop_id);
  END IF;

  IF p_payment_type = 'refund' THEN
    IF p_amount > COALESCE(v_order.amount_paid, 0) THEN
      RAISE EXCEPTION 'Refund cannot exceed amount already paid';
    END IF;
    v_new_amount_paid := GREATEST(COALESCE(v_order.amount_paid, 0) - p_amount, 0);
    v_order.deposit_amount := LEAST(COALESCE(v_order.deposit_amount, 0), v_new_amount_paid);
    IF v_new_amount_paid = 0 THEN
      v_order.payment_status := 'refunded';
    END IF;
  ELSE
    IF COALESCE(v_order.amount_paid, 0) + p_amount > COALESCE(v_order.sale_price, 0) THEN
      RAISE EXCEPTION 'Payment exceeds order sale price';
    END IF;
    v_new_amount_paid := COALESCE(v_order.amount_paid, 0) + p_amount;
    v_order.amount_paid := v_new_amount_paid;
    IF p_payment_type = 'deposit' THEN
      v_order.deposit_amount := COALESCE(v_order.deposit_amount, 0) + p_amount;
    ELSIF p_payment_type = 'cod' THEN
      v_order.payment_status := 'cod';
    END IF;
  END IF;

  v_order.amount_paid := v_new_amount_paid;
  v_order := public.normalize_order_financials(v_order);

  INSERT INTO payments (
    order_id, payment_type, amount, payment_method, payment_date,
    reference_code, note, recorded_by
  ) VALUES (
    p_order_id,
    p_payment_type,
    p_amount,
    COALESCE(NULLIF(btrim(p_payment_method), ''), 'transfer_cash'),
    COALESCE(p_payment_date, CURRENT_DATE),
    p_reference_code,
    p_note,
    p_recorded_by
  ) RETURNING * INTO v_payment;

  INSERT INTO financial_records (
    record_type, category, amount, order_id, payment_id, occurred_on,
    payment_method, note, recorded_by
  ) VALUES (
    CASE WHEN p_payment_type = 'refund' THEN 'refund' ELSE 'income' END,
    p_payment_type,
    p_amount,
    p_order_id,
    v_payment.id,
    COALESCE(p_payment_date, CURRENT_DATE),
    COALESCE(NULLIF(btrim(p_payment_method), ''), 'transfer_cash'),
    p_note,
    p_recorded_by
  ) RETURNING * INTO v_financial;

  UPDATE orders
  SET amount_paid = v_order.amount_paid,
      deposit_amount = v_order.deposit_amount,
      debt_amount = v_order.debt_amount,
      payment_status = v_order.payment_status,
      laptop_locked = v_order.laptop_locked,
      updated_at = timezone('utc'::text, now())
  WHERE id = p_order_id
  RETURNING * INTO v_order;

  v_new_uses := public.order_uses_laptop(
    v_order.laptop_id,
    v_order.is_active,
    v_order.order_status,
    v_order.payment_status,
    v_order.reservation_expires_at
  );
  v_new_committed := v_new_uses AND v_order.order_status IN ('prepared', 'shipping', 'done');
  IF v_order.laptop_id IS NOT NULL THEN
    v_laptop := public.refresh_laptop_inventory(v_order.laptop_id);
    IF v_old_uses IS DISTINCT FROM v_new_uses
       OR v_old_committed IS DISTINCT FROM v_new_committed THEN
      INSERT INTO stock_movements (laptop_id, order_id, movement_type, note, performed_by)
      VALUES (
        v_order.laptop_id,
        v_order.id,
        CASE
          WHEN NOT v_new_uses THEN 'RELEASED'
          WHEN v_new_committed THEN 'SOLD'
          ELSE 'RESERVED'
        END,
        'Laptop state synchronized by payment',
        p_recorded_by
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'payment', to_jsonb(v_payment),
    'financial_record', to_jsonb(v_financial),
    'order', to_jsonb(v_order),
    'laptop', CASE WHEN v_laptop.id IS NULL THEN NULL ELSE to_jsonb(v_laptop) END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.record_order_payment_with_account(p_order_id bigint, p_amount numeric, p_payment_type text, p_payment_method text, p_payment_date date, p_reference_code text, p_note text, p_recorded_by text, p_account_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result jsonb;p payments%ROWTYPE;a cash_accounts%ROWTYPE;t account_transactions%ROWTYPE;occurred timestamptz:=coalesce(p_payment_date,current_date)::timestamptz;
BEGIN
 IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 90 THEN RAISE EXCEPTION 'Idempotency key không hợp lệ';END IF;
 SELECT * INTO p FROM payments WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN
   IF p.account_id IS DISTINCT FROM p_account_id THEN RAISE EXCEPTION 'Idempotency key đã dùng cho tài khoản khác';END IF;
   SELECT jsonb_build_object('payment',to_jsonb(p),'order',to_jsonb(o),'account_transaction',to_jsonb(x)) INTO result
   FROM orders o LEFT JOIN account_transactions x ON x.reference_type='PAYMENT' AND x.reference_id=p.id::text WHERE o.id=p.order_id;
   RETURN result;
 END IF;
 a:=assert_cash_account(p_account_id,'VND',occurred);
 result:=record_order_payment(p_order_id,p_amount,p_payment_type,p_payment_method,coalesce(p_payment_date,current_date),p_reference_code,p_note,p_recorded_by);
 p:=jsonb_populate_record(NULL::payments,result->'payment');
 UPDATE payments SET account_id=a.id,idempotency_key=p_idempotency_key WHERE id=p.id RETURNING * INTO p;
 INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,created_by)
 VALUES(a.id,CASE WHEN p_payment_type='refund' THEN 'OUT' ELSE 'IN' END,round(p_amount*1000000,0),'VND','PAYMENT',p.id::text,'CUSTOMER_PAYMENT',occurred,left(coalesce(p_note,'Thanh toán đơn #'||p_order_id),1000),p_idempotency_key||'-CASH',p_recorded_by) RETURNING * INTO t;
 RETURN jsonb_set(jsonb_set(result,'{payment}',to_jsonb(p)),'{account_transaction}',to_jsonb(t));
END $function$

CREATE OR REPLACE FUNCTION public.record_supplier_payment(p_batch_id bigint, p_amount_rmb numeric, p_exchange_rate numeric, p_method text, p_reference text, p_date date, p_notes text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b purchase_batches%ROWTYPE; paid numeric; total numeric; result supplier_payments%ROWTYPE;
BEGIN
  SELECT * INTO result FROM supplier_payments WHERE idempotency_key=p_idempotency_key;
  IF FOUND THEN RETURN to_jsonb(result); END IF;
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 90 THEN
    RAISE EXCEPTION 'Idempotency key không hợp lệ';
  END IF;
  SELECT * INTO b FROM purchase_batches WHERE id=p_batch_id FOR UPDATE;
  IF NOT FOUND OR b.active IS NOT TRUE OR b.status='CANCELLED' THEN
    RAISE EXCEPTION 'Lô mua không tồn tại hoặc không còn nhận thanh toán';
  END IF;
  SELECT coalesce(sum(purchase_price_rmb),0) INTO total
  FROM laptops WHERE purchase_batch_id=b.id AND status<>'ignored';
  SELECT coalesce(sum(amount_rmb),0) INTO paid
  FROM supplier_payments WHERE purchase_batch_id=b.id;
  IF p_amount_rmb IS NULL OR p_amount_rmb<=0 OR p_amount_rmb>total-paid THEN
    RAISE EXCEPTION 'Số tiền vượt công nợ còn lại';
  END IF;
  IF p_exchange_rate IS NULL OR p_exchange_rate<=0 THEN RAISE EXCEPTION 'Tỷ giá không hợp lệ'; END IF;
  IF p_method NOT IN('WECHAT','ALIPAY','BANK_TRANSFER','CASH','OTHER') THEN
    RAISE EXCEPTION 'Phương thức thanh toán không hợp lệ';
  END IF;
  INSERT INTO supplier_payments(
    supplier_id,purchase_batch_id,amount_rmb,amount_vnd,exchange_rate,payment_method,
    reference,payment_date,notes,recorded_by,idempotency_key
  ) VALUES(
    b.supplier_id,b.id,p_amount_rmb,round(p_amount_rmb*p_exchange_rate,2),p_exchange_rate,
    p_method,left(coalesce(p_reference,''),200),coalesce(p_date,current_date),
    left(coalesce(p_notes,''),2000),p_actor,p_idempotency_key
  ) RETURNING * INTO result;
  RETURN to_jsonb(result);
EXCEPTION WHEN unique_violation THEN
  SELECT * INTO result FROM supplier_payments WHERE idempotency_key=p_idempotency_key;
  IF FOUND THEN RETURN to_jsonb(result); END IF;
  RAISE;
END $function$

CREATE OR REPLACE FUNCTION public.record_supplier_payment_with_account(p_batch_id bigint, p_amount_rmb numeric, p_exchange_rate numeric, p_method text, p_reference text, p_date date, p_notes text, p_actor text, p_account_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result supplier_payments%ROWTYPE;a cash_accounts%ROWTYPE;t account_transactions%ROWTYPE;
BEGIN
 IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 90 THEN RAISE EXCEPTION 'Idempotency key không hợp lệ';END IF;
 SELECT * INTO result FROM supplier_payments WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN IF result.account_id IS DISTINCT FROM p_account_id THEN RAISE EXCEPTION 'Idempotency key đã dùng cho tài khoản khác';END IF;RETURN to_jsonb(result);END IF;
 a:=assert_cash_account(p_account_id,'CNY',coalesce(p_date,current_date)::timestamptz);
 result:=jsonb_populate_record(NULL::supplier_payments,record_supplier_payment(p_batch_id,p_amount_rmb,p_exchange_rate,p_method,p_reference,coalesce(p_date,current_date),p_notes,p_actor,p_idempotency_key));
 PERFORM set_config('app.financial_account_link','on',true);
 UPDATE supplier_payments SET account_id=a.id WHERE id=result.id RETURNING * INTO result;
 INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,created_by)
 VALUES(a.id,'OUT',p_amount_rmb,'CNY','SUPPLIER_PAYMENT',result.id::text,'SUPPLIER_PAYMENT',coalesce(p_date,current_date)::timestamptz,left(coalesce(p_notes,'Thanh toán lô #'||p_batch_id),1000),p_idempotency_key||'-CASH',p_actor) RETURNING * INTO t;
 RETURN to_jsonb(result);
END $function$

CREATE OR REPLACE FUNCTION public.record_supplier_refund(p_return_id uuid, p_amount_rmb numeric, p_exchange_rate numeric, p_method text, p_reference text, p_received_at timestamp with time zone, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r supplier_returns%ROWTYPE;refund supplier_refunds%ROWTYPE;limit_amount numeric;refunded numeric;
BEGIN
 SELECT * INTO refund FROM supplier_refunds WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(refund);END IF;
 SELECT * INTO r FROM supplier_returns WHERE id=p_return_id FOR UPDATE;IF NOT FOUND OR r.status NOT IN('WAITING_REFUND','PARTIALLY_RESOLVED') THEN RAISE EXCEPTION 'Phiếu trả chưa ở trạng thái nhận hoàn tiền';END IF;
 SELECT coalesce(sum(coalesce(agreed_refund_rmb,expected_refund_rmb)),0) INTO limit_amount FROM supplier_return_items WHERE supplier_return_id=r.id AND status<>'CANCELLED';
 SELECT coalesce(sum(amount_rmb),0) INTO refunded FROM supplier_refunds WHERE supplier_return_id=r.id;
 IF p_amount_rmb<=0 OR limit_amount<=0 OR p_amount_rmb>limit_amount-refunded THEN RAISE EXCEPTION 'Số tiền hoàn vượt số còn phải nhận';END IF;
 IF p_exchange_rate IS NOT NULL AND p_exchange_rate<=0 THEN RAISE EXCEPTION 'Tỷ giá không hợp lệ';END IF;
 INSERT INTO supplier_refunds(supplier_id,supplier_return_id,amount_rmb,amount_vnd,exchange_rate,refund_method,reference,received_at,idempotency_key,created_by)
 VALUES(r.supplier_id,r.id,p_amount_rmb,CASE WHEN p_exchange_rate IS NULL THEN NULL ELSE round(p_amount_rmb*p_exchange_rate,2) END,p_exchange_rate,p_method,left(coalesce(p_reference,''),300),coalesce(p_received_at,timezone('utc',now())),p_idempotency_key,p_actor) RETURNING * INTO refund;
 refunded:=refunded+p_amount_rmb;
 UPDATE supplier_returns SET status=CASE WHEN refunded>=limit_amount THEN 'REFUNDED' ELSE 'PARTIALLY_RESOLVED' END WHERE id=r.id;
 IF refunded>=limit_amount THEN UPDATE supplier_return_items SET status='REFUNDED' WHERE supplier_return_id=r.id AND status<>'CANCELLED';END IF;
 INSERT INTO supplier_return_events(supplier_return_id,event_type,details,performed_by) VALUES(r.id,'REFUND_RECEIVED',jsonb_build_object('amount_rmb',p_amount_rmb,'refunded_rmb',refunded,'remaining_rmb',greatest(limit_amount-refunded,0)),p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('SUPPLIER_REFUND',refund.id::text,'CREATE',jsonb_build_object('supplier_return_id',r.id,'amount_rmb',p_amount_rmb),p_actor);
 RETURN to_jsonb(refund);
EXCEPTION WHEN unique_violation THEN SELECT * INTO refund FROM supplier_refunds WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(refund);END IF;RAISE;
END $function$

CREATE OR REPLACE FUNCTION public.record_supplier_refund_with_account(p_return_id uuid, p_amount_rmb numeric, p_exchange_rate numeric, p_method text, p_reference text, p_received_at timestamp with time zone, p_actor text, p_account_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result supplier_refunds%ROWTYPE;a cash_accounts%ROWTYPE;t account_transactions%ROWTYPE;occurred timestamptz:=coalesce(p_received_at,timezone('utc',now()));
BEGIN
 IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 90 THEN RAISE EXCEPTION 'Idempotency key không hợp lệ';END IF;
 SELECT * INTO result FROM supplier_refunds WHERE idempotency_key=p_idempotency_key;
 IF FOUND THEN IF result.account_id IS DISTINCT FROM p_account_id THEN RAISE EXCEPTION 'Idempotency key đã dùng cho tài khoản khác';END IF;RETURN to_jsonb(result);END IF;
 a:=assert_cash_account(p_account_id,'CNY',occurred);
 result:=jsonb_populate_record(NULL::supplier_refunds,record_supplier_refund(p_return_id,p_amount_rmb,p_exchange_rate,p_method,p_reference,occurred,p_actor,p_idempotency_key));
 PERFORM set_config('app.financial_account_link','on',true);
 UPDATE supplier_refunds SET account_id=a.id WHERE id=result.id RETURNING * INTO result;
 INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,created_by)
 VALUES(a.id,'IN',p_amount_rmb,'CNY','SUPPLIER_REFUND',result.id::text,'SUPPLIER_REFUND',occurred,left(coalesce(p_reference,'Hoàn tiền nhà cung cấp'),1000),p_idempotency_key||'-CASH',p_actor) RETURNING * INTO t;
 RETURN to_jsonb(result);
END $function$

CREATE OR REPLACE FUNCTION public.refresh_laptop_inventory(p_laptop_id bigint)
 RETURNS laptops
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; has_committed boolean; has_reserved boolean;
BEGIN
  IF p_laptop_id IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO l FROM laptops WHERE id=p_laptop_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laptop % không tồn tại',p_laptop_id; END IF;
  UPDATE orders SET laptop_locked=public.order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at)
  WHERE laptop_id=p_laptop_id AND laptop_locked IS DISTINCT FROM public.order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at);
  SELECT exists(SELECT 1 FROM orders WHERE laptop_id=p_laptop_id
    AND public.order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at)
    AND order_status IN('prepared','shipping','done')) INTO has_committed;
  SELECT exists(SELECT 1 FROM orders WHERE laptop_id=p_laptop_id
    AND is_active IS TRUE AND coalesce(payment_status,'')<>'refunded'
    AND coalesce(order_status,'') NOT IN('cancelled','returned')
    AND (public.order_uses_laptop(laptop_id,is_active,order_status,payment_status,reservation_expires_at)
      OR ((order_status='deposited' OR payment_status='deposited')
        AND (reservation_expires_at IS NULL OR reservation_expires_at>CURRENT_TIMESTAMP)))) INTO has_reserved;
  PERFORM set_config('app.laptop_transition','on',true);
  UPDATE laptops SET status=CASE
      WHEN status IN('in_transit','waiting_qc','repair','supplier_return','ignored') THEN status
      WHEN has_committed THEN 'sold'
      WHEN has_reserved THEN 'reserved'
      ELSE 'available' END,
    sold_at=CASE WHEN has_committed THEN coalesce(sold_at,timezone('utc',now())) ELSE sold_at END
  WHERE id=p_laptop_id RETURNING * INTO l;
  RETURN l;
END $function$

CREATE OR REPLACE FUNCTION public.save_order_demand(p_order jsonb, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE saved orders; source laptops;
BEGIN
 SELECT * INTO saved FROM orders WHERE id=(p_result->'order'->>'id')::bigint;
 IF NOT FOUND THEN RAISE EXCEPTION 'Order save did not return an order'; END IF;
 IF p_order ? 'requested_laptop_id' THEN
   SELECT * INTO source FROM laptops WHERE id=nullif(p_order->>'requested_laptop_id','')::bigint;
   UPDATE orders SET requested_laptop_id=source.id,
     requested_configuration=CASE WHEN requested_laptop_id IS DISTINCT FROM source.id OR requested_configuration IS NULL THEN coalesce(source.name,requested_configuration) ELSE requested_configuration END,
     requested_category=CASE WHEN requested_laptop_id IS DISTINCT FROM source.id OR requested_configuration IS NULL THEN coalesce(source.category,requested_category) ELSE requested_category END
   WHERE id=saved.id RETURNING * INTO saved;
 END IF;
 RETURN jsonb_set(p_result,'{order}',to_jsonb(saved));
END $function$

CREATE OR REPLACE FUNCTION public.save_order_invoice_fields(p_order jsonb, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id bigint := (p_result->'order'->>'id')::bigint; v_row orders%ROWTYPE;
BEGIN
 IF p_order ? 'gift_accessory_ids' AND (jsonb_typeof(p_order->'gift_accessory_ids') <> 'array' OR jsonb_array_length(p_order->'gift_accessory_ids') > 30) THEN
   RAISE EXCEPTION 'Danh sách quà tặng không hợp lệ';
 END IF;
 IF p_order ? 'gift_accessory_ids' AND EXISTS (
   SELECT 1 FROM jsonb_array_elements_text(p_order->'gift_accessory_ids') x(id)
   WHERE NOT EXISTS (SELECT 1 FROM accessories a WHERE a.id::text = x.id AND a.active)
 ) THEN RAISE EXCEPTION 'Phụ kiện không tồn tại hoặc đã ngừng sử dụng'; END IF;
 UPDATE orders SET
   branch_id = CASE WHEN p_order ? 'branch_id' THEN (p_order->>'branch_id')::bigint ELSE branch_id END,
   gift_accessory_ids = CASE WHEN p_order ? 'gift_accessory_ids' THEN p_order->'gift_accessory_ids' ELSE gift_accessory_ids END,
   gift_preset = CASE WHEN p_order ? 'gift_preset' THEN coalesce(p_order->>'gift_preset','') ELSE gift_preset END
 WHERE id = v_id RETURNING * INTO v_row;
 RETURN jsonb_set(p_result,'{order}',to_jsonb(v_row));
END $function$

