CREATE OR REPLACE FUNCTION public.snapshot_order_cost()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  import_cost_vnd numeric;
  direct_cost numeric;
  sale_vnd numeric;
BEGIN
  IF NEW.laptop_id IS NOT NULL AND NEW.sale_price IS NOT NULL THEN
    SELECT round(l.import_price_vnd * 1000000, 2)
      INTO import_cost_vnd
      FROM public.laptops l
     WHERE l.id = NEW.laptop_id;

    NEW.profit_vnd := CASE
      WHEN import_cost_vnd IS NULL THEN 0
      ELSE round(NEW.sale_price - (import_cost_vnd / 1000000), 4)
    END;
  ELSE
    NEW.profit_vnd := 0;
  END IF;

  IF NEW.order_status IN ('prepared', 'shipping', 'done')
     AND NEW.cost_snapshotted_at IS NULL
     AND NEW.laptop_id IS NOT NULL THEN
    sale_vnd := coalesce(NEW.sale_price, 0) * 1000000;
    direct_cost := coalesce(NEW.credit_card_fee, 0) * 1000000;

    NEW.cost_snapshot_vnd := import_cost_vnd;
    NEW.gross_profit_snapshot_vnd := CASE
      WHEN import_cost_vnd IS NULL THEN NULL
      ELSE sale_vnd - import_cost_vnd
    END;
    NEW.direct_cost_snapshot_vnd := direct_cost;
    NEW.net_contribution_snapshot_vnd := CASE
      WHEN import_cost_vnd IS NULL THEN NULL
      ELSE sale_vnd - import_cost_vnd - direct_cost
    END;
    NEW.cost_snapshot_status := CASE
      WHEN import_cost_vnd IS NULL THEN 'INCOMPLETE'
      ELSE 'COMPLETE'
    END;
    NEW.cost_snapshot_reasons := CASE
      WHEN import_cost_vnd IS NULL THEN jsonb_build_array('MISSING_IMPORT_PRICE_VND')
      ELSE '[]'::jsonb
    END;
    NEW.cost_snapshotted_at := timezone('utc', now());
    INSERT INTO public.activity_logs(entity_type, entity_id, action, changes, user_name)
    VALUES (
      'ORDER',
      coalesce(NEW.id::text, 'pending'),
      'UPDATE',
      jsonb_build_object(
        'event', 'COST_SNAPSHOT_CREATED',
        'cost_source', 'laptops.import_price_vnd',
        'laptop_id', NEW.laptop_id,
        'cost_snapshot_vnd', NEW.cost_snapshot_vnd,
        'cost_status', NEW.cost_snapshot_status
      ),
      'SYSTEM'
    );
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.start_qc_inspection(p_laptop_id bigint, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; q qc_inspections%ROWTYPE;
BEGIN
  IF length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN
    RAISE EXCEPTION 'Mã chống gửi trùng không hợp lệ';
  END IF;
  SELECT * INTO l FROM laptops WHERE id=p_laptop_id AND is_active IS TRUE FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy máy'; END IF;
  SELECT * INTO q FROM qc_inspections WHERE idempotency_key=p_idempotency_key;
  IF FOUND THEN
    IF q.laptop_id<>l.id THEN RAISE EXCEPTION 'Mã chống gửi trùng đã dùng cho máy khác'; END IF;
    RETURN to_jsonb(q);
  END IF;
  IF l.status<>'waiting_qc' THEN RAISE EXCEPTION 'Máy không ở trạng thái chờ QC'; END IF;
  SELECT * INTO q FROM qc_inspections WHERE laptop_id=l.id AND status='IN_PROGRESS';
  IF FOUND THEN RETURN to_jsonb(q); END IF;
  INSERT INTO qc_inspections(inspection_code,laptop_id,started_by,idempotency_key)
  VALUES(next_qc_inspection_code(),l.id,p_actor,p_idempotency_key) RETURNING * INTO q;
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('QC_INSPECTION',q.id::text,'CREATE',jsonb_build_object('laptop_id',l.id,'inspection_code',q.inspection_code),p_actor);
  RETURN to_jsonb(q);
END;
$function$

CREATE OR REPLACE FUNCTION public.start_repair_job(p_data jsonb, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; j repair_jobs%ROWTYPE; sid text:=nullif(p_data->>'source_id',''); assignee uuid:=nullif(p_data->>'assigned_to','')::uuid;
BEGIN
 SELECT * INTO j FROM repair_jobs WHERE idempotency_key=p_idempotency_key; IF FOUND THEN RETURN to_jsonb(j); END IF;
 PERFORM validate_repair_assignee(assignee);
 SELECT * INTO l FROM laptops WHERE id=(p_data->>'laptop_id')::bigint AND is_active FOR UPDATE;
 IF NOT FOUND OR l.status<>'waiting_qc' THEN RAISE EXCEPTION 'Laptop không ở trạng thái được tạo phiếu sửa'; END IF;
 IF p_data->>'source_type'='QC' AND (sid IS NULL OR NOT EXISTS(SELECT 1 FROM qc_inspections WHERE id::text=sid AND laptop_id=l.id AND result='FAIL')) THEN RAISE EXCEPTION 'QC nguồn không hợp lệ'; END IF;
 INSERT INTO repair_jobs(repair_code,laptop_id,source_type,source_id,reported_issue,priority,assigned_to,requires_re_qc,created_by,idempotency_key)
 VALUES(next_repair_code(),l.id,p_data->>'source_type',sid,btrim(p_data->>'reported_issue'),coalesce(p_data->>'priority','NORMAL'),assignee,true,p_actor,p_idempotency_key) RETURNING * INTO j;
 PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='repair',available_for_sale_at=NULL WHERE id=l.id;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'CREATE',jsonb_build_object('repair_code',j.repair_code,'laptop_id',l.id),p_actor);
 RETURN to_jsonb(j);
END $function$

