CREATE OR REPLACE FUNCTION public.sync_laptop_cost_components(p_laptop_id bigint, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; r repair_jobs%ROWTYPE; repair_count integer:=0;
BEGIN
  SELECT * INTO l FROM laptops WHERE id=p_laptop_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy laptop'; END IF;
  FOR r IN SELECT * FROM repair_jobs WHERE laptop_id=l.id AND status='COMPLETED' LOOP
    INSERT INTO laptop_cost_components(laptop_id,cost_type,amount_vnd,source_type,source_id,description,occurred_at,created_by)
    VALUES(l.id,'REPAIR',round(r.total_cost_vnd,0),'REPAIR_JOB',r.id::text,'Chi phí '||r.repair_code,coalesce(r.completed_at,r.updated_at),p_actor)
    ON CONFLICT(laptop_id,source_type,source_id,cost_type) WHERE source_id IS NOT NULL AND voided_at IS NULL
    DO UPDATE SET amount_vnd=excluded.amount_vnd,description=excluded.description;
    repair_count:=repair_count+1;
  END LOOP;
  RETURN jsonb_build_object('laptop_id',l.id,'repair_jobs_synced',repair_count);
END $function$

CREATE OR REPLACE FUNCTION public.sync_laptop_purchase_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.purchase_price_rmb IS DISTINCT FROM OLD.purchase_price_rmb THEN
      IF NEW.price_rmb IS DISTINCT FROM OLD.price_rmb AND NEW.price_rmb IS DISTINCT FROM NEW.purchase_price_rmb THEN
        RAISE EXCEPTION 'Giá mua và giá nhập không thống nhất';
      END IF;
      NEW.price_rmb := NEW.purchase_price_rmb;
    ELSIF NEW.price_rmb IS DISTINCT FROM OLD.price_rmb THEN
      NEW.purchase_price_rmb := coalesce(NEW.price_rmb,0);
    END IF;
    IF NEW.purchase_exchange_rate IS DISTINCT FROM OLD.purchase_exchange_rate THEN
      IF NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate AND NEW.exchange_rate IS DISTINCT FROM NEW.purchase_exchange_rate THEN
        RAISE EXCEPTION 'Tỷ giá mua và tỷ giá nhập không thống nhất';
      END IF;
      NEW.exchange_rate := NEW.purchase_exchange_rate;
    ELSIF NEW.exchange_rate IS DISTINCT FROM OLD.exchange_rate THEN
      NEW.purchase_exchange_rate := NEW.exchange_rate;
    END IF;
    IF NEW.tracking_code_cn IS DISTINCT FROM OLD.tracking_code_cn THEN
      NEW.tracking_code := nullif(NEW.tracking_code_cn,'');
    ELSIF NEW.tracking_code IS DISTINCT FROM OLD.tracking_code THEN
      NEW.tracking_code_cn := coalesce(NEW.tracking_code,'');
    END IF;
  ELSE
    IF coalesce(NEW.purchase_price_rmb,0)=0 AND coalesce(NEW.price_rmb,0)>0 THEN
      NEW.purchase_price_rmb := NEW.price_rmb;
    END IF;
    NEW.price_rmb := NEW.purchase_price_rmb;
    NEW.purchase_exchange_rate := coalesce(NEW.purchase_exchange_rate,NEW.exchange_rate);
    NEW.exchange_rate := NEW.purchase_exchange_rate;
    NEW.tracking_code_cn := coalesce(nullif(NEW.tracking_code_cn,''),NEW.tracking_code,'');
    NEW.tracking_code := nullif(NEW.tracking_code_cn,'');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.transfer_cash_accounts(p_source uuid, p_destination uuid, p_amount numeric, p_occurred_at timestamp with time zone, p_description text, p_actor text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE src cash_accounts%ROWTYPE;dst cash_accounts%ROWTYPE;gid uuid:=gen_random_uuid();existing account_transactions%ROWTYPE;
BEGIN SELECT * INTO existing FROM account_transactions WHERE idempotency_key=p_idempotency_key||'-OUT';IF FOUND THEN RETURN jsonb_build_object('transfer_group_id',existing.transfer_group_id);END IF;IF p_source=p_destination OR p_amount<=0 OR btrim(coalesce(p_description,''))='' THEN RAISE EXCEPTION 'Transfer không hợp lệ';END IF;
 src:=assert_cash_account(p_source,(SELECT currency FROM cash_accounts WHERE id=p_source),p_occurred_at);dst:=assert_cash_account(p_destination,src.currency,p_occurred_at);
 INSERT INTO account_transactions(account_id,direction,amount,currency,reference_type,reference_id,transaction_type,occurred_at,description,idempotency_key,transfer_group_id,created_by) VALUES
 (src.id,'OUT',p_amount,src.currency,'TRANSFER',gid::text,'TRANSFER_OUT',p_occurred_at,left(p_description,1000),p_idempotency_key||'-OUT',gid,p_actor),
 (dst.id,'IN',p_amount,dst.currency,'TRANSFER',gid::text,'TRANSFER_IN',p_occurred_at,left(p_description,1000),p_idempotency_key||'-IN',gid,p_actor);
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('ACCOUNT_TRANSFER',gid::text,'CREATE',jsonb_build_object('event','ACCOUNT_TRANSFER','source',src.id,'destination',dst.id,'amount',p_amount,'currency',src.currency),p_actor);RETURN jsonb_build_object('transfer_group_id',gid);END $function$

CREATE OR REPLACE FUNCTION public.transition_cod_receivable(p_id uuid, p_target text, p_expected_settlement_at timestamp with time zone, p_notes text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c cod_receivables%ROWTYPE;result jsonb;
BEGIN
 SELECT * INTO c FROM cod_receivables WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy COD';END IF;
 IF p_target='DELIVERED' AND c.status='PENDING_DELIVERY' THEN
   result:=record_order_payment(c.order_id,c.expected_cod_amount_vnd/1000000,'cod','cod',current_date,c.tracking_number,'COD đã giao - chuyển nghĩa vụ phải thu sang đơn vị vận chuyển',p_actor);
   UPDATE cod_receivables SET status='DELIVERED',delivered_at=now(),expected_settlement_at=coalesce(p_expected_settlement_at,expected_settlement_at),notes=left(coalesce(p_notes,notes),2000) WHERE id=c.id RETURNING * INTO c;
 ELSIF p_target='WAITING_SETTLEMENT' AND c.status='DELIVERED' THEN
   UPDATE cod_receivables SET status='WAITING_SETTLEMENT',expected_settlement_at=coalesce(p_expected_settlement_at,expected_settlement_at),notes=left(coalesce(p_notes,notes),2000) WHERE id=c.id RETURNING * INTO c;
 ELSIF p_target='DISPUTED' AND c.status IN('DELIVERED','WAITING_SETTLEMENT','PARTIALLY_SETTLED') THEN
   UPDATE cod_receivables SET status='DISPUTED',notes=left(coalesce(p_notes,notes),2000) WHERE id=c.id RETURNING * INTO c;
 ELSIF p_target IN('RETURNED','CANCELLED') AND c.status='PENDING_DELIVERY' THEN
   UPDATE cod_receivables SET status=p_target,notes=left(coalesce(p_notes,notes),2000) WHERE id=c.id RETURNING * INTO c;
 ELSE RAISE EXCEPTION 'Chuyển trạng thái COD không hợp lệ';END IF;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('COD_RECEIVABLE',c.id::text,'UPDATE',jsonb_build_object('event','COD_'||p_target,'status',p_target),p_actor);
 RETURN to_jsonb(c);
END $function$

CREATE OR REPLACE FUNCTION public.transition_supplier_return(p_id uuid, p_target text, p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r supplier_returns%ROWTYPE; resolution text:=nullif(p_data->>'resolution_type','');
BEGIN
 SELECT * INTO r FROM supplier_returns WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu trả nhà cung cấp'; END IF;
 PERFORM set_config('app.supplier_return_transition','on',true);
 IF NOT ((r.status='DRAFT' AND p_target IN('APPROVED','CANCELLED')) OR (r.status='APPROVED' AND p_target IN('READY_TO_SHIP','CANCELLED')) OR
  (r.status='READY_TO_SHIP' AND p_target IN('SHIPPED','CANCELLED')) OR (r.status='SHIPPED' AND p_target='SUPPLIER_RECEIVED') OR
  (r.status='SUPPLIER_RECEIVED' AND p_target IN('WAITING_REFUND','WAITING_REPLACEMENT','REJECTED')) OR
  (r.status IN('REFUNDED','REPLACED','REJECTED') AND p_target='CLOSED')) THEN RAISE EXCEPTION 'Chuyển trạng thái trả NCC không hợp lệ'; END IF;
 IF p_target='SHIPPED' AND (btrim(coalesce(p_data->>'carrier',r.return_carrier,''))='' OR btrim(coalesce(p_data->>'tracking_number',r.return_tracking_number,''))='') THEN RAISE EXCEPTION 'Cần đơn vị vận chuyển và tracking'; END IF;
 UPDATE supplier_returns SET status=p_target,resolution_type=coalesce(resolution,resolution_type),
  return_carrier=left(coalesce(nullif(p_data->>'carrier',''),return_carrier),160),return_tracking_number=left(coalesce(nullif(p_data->>'tracking_number',''),return_tracking_number),200),
  approved_by=CASE WHEN p_target='APPROVED' THEN p_actor ELSE approved_by END,approved_at=CASE WHEN p_target='APPROVED' THEN timezone('utc',now()) ELSE approved_at END,
  shipped_at=CASE WHEN p_target='SHIPPED' THEN timezone('utc',now()) ELSE shipped_at END,supplier_received_at=CASE WHEN p_target='SUPPLIER_RECEIVED' THEN timezone('utc',now()) ELSE supplier_received_at END,
  closed_at=CASE WHEN p_target IN('CLOSED','CANCELLED') THEN timezone('utc',now()) ELSE closed_at END WHERE id=r.id RETURNING * INTO r;
 IF p_target IN('APPROVED','READY_TO_SHIP','SHIPPED','SUPPLIER_RECEIVED','WAITING_REFUND','WAITING_REPLACEMENT') THEN
  PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops SET status='supplier_return',available_for_sale_at=NULL WHERE id IN(SELECT laptop_id FROM supplier_return_items WHERE supplier_return_id=r.id);
 END IF;
 IF p_target='CANCELLED' THEN
  PERFORM set_config('app.laptop_transition','on',true); UPDATE laptops l SET status=coalesce(i.previous_laptop_status,'waiting_qc') FROM supplier_return_items i WHERE i.supplier_return_id=r.id AND i.laptop_id=l.id;
  UPDATE supplier_return_items SET status='CANCELLED' WHERE supplier_return_id=r.id;
 END IF;
 IF p_target='SHIPPED' THEN UPDATE supplier_return_items SET status='SHIPPED' WHERE supplier_return_id=r.id; END IF;
 IF p_target='SUPPLIER_RECEIVED' THEN UPDATE supplier_return_items SET status='SUPPLIER_RECEIVED' WHERE supplier_return_id=r.id; END IF;
 INSERT INTO supplier_return_events(supplier_return_id,event_type,details,performed_by) VALUES(r.id,p_target,jsonb_build_object('resolution_type',r.resolution_type),p_actor);
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION public.update_cash_account(p_id uuid, p_name text, p_is_active boolean, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a cash_accounts%ROWTYPE;
BEGIN
 SELECT * INTO a FROM cash_accounts WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy tài khoản';END IF;
 IF btrim(coalesce(p_name,''))='' THEN RAISE EXCEPTION 'Tên tài khoản không hợp lệ';END IF;
 IF p_is_active=false AND EXISTS(SELECT 1 FROM account_transactions WHERE account_id=p_id) THEN
   RAISE EXCEPTION 'Tài khoản đã có giao dịch; chỉ được ngừng sử dụng sau khi xác nhận số dư và chuyển tiền';
 END IF;
 UPDATE cash_accounts SET name=left(btrim(p_name),160),is_active=coalesce(p_is_active,is_active) WHERE id=p_id RETURNING * INTO a;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('CASH_ACCOUNT',a.id::text,'UPDATE',jsonb_build_object('event','CASH_ACCOUNT_UPDATED','name',a.name,'is_active',a.is_active),p_actor);
 RETURN to_jsonb(a);
END $function$

CREATE OR REPLACE FUNCTION public.update_incoming_tracking(p_laptop_id bigint, p_tracking text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; old_tracking text;
  normalized text:=left(btrim(coalesce(p_tracking,'')),200);
BEGIN
  SELECT tracking_code_cn INTO old_tracking
  FROM laptops WHERE id=p_laptop_id AND is_active IS TRUE FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laptop không tồn tại hoặc đã ngừng sử dụng'; END IF;
  UPDATE laptops SET tracking_code_cn=normalized,tracking_code=nullif(normalized,'')
  WHERE id=p_laptop_id RETURNING * INTO l;
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('LAPTOP',l.id::text,'UPDATE',jsonb_build_object(
    'event','TRACKING_CORRECTED','old',old_tracking,'new',l.tracking_code_cn),p_actor);
  RETURN to_jsonb(l);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_laptop_procurement(p_laptop_id bigint, p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE l laptops%ROWTYPE; target_batch purchase_batches%ROWTYPE; next_tracking text;
BEGIN
  SELECT * INTO l FROM laptops WHERE id=p_laptop_id AND is_active IS TRUE FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laptop không tồn tại hoặc đã ngừng sử dụng'; END IF;
  IF l.status='sold' THEN RAISE EXCEPTION 'Laptop đã bán: dữ liệu mua hàng là bất biến'; END IF;
  IF l.status='supplier_return' AND EXISTS(
    SELECT 1 FROM supplier_refunds sr
    JOIN supplier_return_items sri ON sri.supplier_return_id=sr.supplier_return_id
    WHERE sri.laptop_id=l.id
  ) THEN RAISE EXCEPTION 'Laptop đang trả NCC và đã phát sinh tài chính'; END IF;
  IF l.status NOT IN('in_transit','waiting_qc','repair','available','reserved','supplier_return') THEN
    RAISE EXCEPTION 'Trạng thái laptop không cho phép sửa dữ liệu mua hàng';
  END IF;
  IF p_data ? 'name' AND length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 240 THEN
    RAISE EXCEPTION 'Tên máy không hợp lệ';
  END IF;
  IF p_data ? 'category' AND NOT EXISTS(
    SELECT 1 FROM app_options o WHERE o.group_key='category'
      AND o.option_key=p_data->>'category' AND o.is_active IS TRUE
  ) THEN RAISE EXCEPTION 'Phân loại máy không hợp lệ'; END IF;
  IF p_data ? 'purchase_price_rmb' AND (p_data->>'purchase_price_rmb')::numeric < 0 THEN
    RAISE EXCEPTION 'Giá mua không hợp lệ';
  END IF;
  IF p_data ? 'shipping_rmb' AND coalesce(nullif(p_data->>'shipping_rmb','')::numeric,0) < 0 THEN
    RAISE EXCEPTION 'Phí vận chuyển không hợp lệ';
  END IF;
  IF p_data ? 'import_price_vnd' AND nullif(p_data->>'import_price_vnd','') IS NOT NULL
     AND (p_data->>'import_price_vnd')::numeric < 0 THEN
    RAISE EXCEPTION 'Giá nhập VNĐ không hợp lệ';
  END IF;
  next_tracking:=CASE WHEN p_data ? 'tracking_code_cn'
    THEN left(btrim(coalesce(p_data->>'tracking_code_cn','')),200)
    ELSE l.tracking_code_cn END;
  IF p_data ? 'purchase_batch_id' THEN
    SELECT * INTO target_batch FROM purchase_batches
    WHERE id=(p_data->>'purchase_batch_id')::bigint AND active IS TRUE FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Lô mua đích không tồn tại hoặc đã ngừng sử dụng'; END IF;
    IF EXISTS(SELECT 1 FROM supplier_payments WHERE purchase_batch_id=l.purchase_batch_id)
       AND target_batch.id IS DISTINCT FROM l.purchase_batch_id THEN
      RAISE EXCEPTION 'Không thể chuyển lô sau khi lô nguồn đã phát sinh thanh toán NCC';
    END IF;
  END IF;
  UPDATE laptops SET
    name=CASE WHEN p_data ? 'name' THEN left(btrim(p_data->>'name'),240) ELSE name END,
    category=CASE WHEN p_data ? 'category' THEN p_data->>'category' ELSE category END,
    serial=CASE WHEN p_data ? 'serial' THEN nullif(left(btrim(coalesce(p_data->>'serial','')),100),'') ELSE serial END,
    tracking_code_cn=next_tracking,tracking_code=nullif(next_tracking,''),
    purchase_price_rmb=CASE WHEN p_data ? 'purchase_price_rmb' THEN (p_data->>'purchase_price_rmb')::numeric ELSE purchase_price_rmb END,
    price_rmb=CASE WHEN p_data ? 'purchase_price_rmb' THEN (p_data->>'purchase_price_rmb')::numeric ELSE price_rmb END,
    shipping_rmb=CASE WHEN p_data ? 'shipping_rmb' THEN coalesce(nullif(p_data->>'shipping_rmb','')::numeric,0) ELSE shipping_rmb END,
    import_price_vnd=CASE WHEN p_data ? 'import_price_vnd' AND nullif(p_data->>'import_price_vnd','') IS NOT NULL
      THEN (p_data->>'import_price_vnd')::numeric ELSE import_price_vnd END,
    condition_note=CASE WHEN p_data ? 'notes' THEN left(coalesce(p_data->>'notes',''),2000) ELSE condition_note END,
    purchase_batch_id=CASE WHEN p_data ? 'purchase_batch_id' THEN target_batch.id ELSE purchase_batch_id END,
    purchase_exchange_rate=CASE WHEN p_data ? 'purchase_batch_id' THEN target_batch.exchange_rate ELSE purchase_exchange_rate END,
    exchange_rate=CASE WHEN p_data ? 'purchase_batch_id' THEN target_batch.exchange_rate ELSE exchange_rate END,
    import_date=CASE WHEN p_data ? 'purchase_batch_id' THEN target_batch.purchase_date ELSE import_date END,
    month_key=CASE WHEN p_data ? 'purchase_batch_id' THEN to_char(target_batch.purchase_date,'MM/YYYY') ELSE month_key END
  WHERE id=l.id RETURNING * INTO l;
  INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name)
  VALUES('LAPTOP',l.id::text,'UPDATE',jsonb_build_object(
    'event','PROCUREMENT_CORRECTED','fields',p_data),p_actor);
  RETURN to_jsonb(l);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_order_before_invoice(p_order jsonb, p_recorded_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_id BIGINT;
  v_existing orders%ROWTYPE;
  v_next orders%ROWTYPE;
  v_order orders%ROWTYPE;
  v_old_laptop laptops%ROWTYPE;
  v_previous_laptop laptops%ROWTYPE;
  v_laptop laptops%ROWTYPE;
  v_old_laptop_id BIGINT;
  v_new_laptop_id BIGINT;
BEGIN
  IF p_order IS NULL OR NOT (p_order ? 'id') THEN
    RAISE EXCEPTION 'Order id is required';
  END IF;

  v_order_id := (p_order->>'id')::BIGINT;
  SELECT * INTO v_existing FROM orders WHERE id = v_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order % does not exist', v_order_id;
  END IF;

  v_next := jsonb_populate_record(v_existing, p_order);
  v_next.id := v_existing.id;
  v_next.created_at := COALESCE(v_next.created_at, v_existing.created_at);
  v_next.updated_at := timezone('utc'::text, now());
  v_next := public.normalize_order_financials(v_next);
  IF v_next.month_key IS NULL OR btrim(v_next.month_key) = '' THEN
    v_next.month_key := COALESCE(v_existing.month_key, TO_CHAR(CURRENT_DATE, 'MM/YYYY'));
  END IF;

  v_old_laptop_id := v_existing.laptop_id;
  v_new_laptop_id := v_next.laptop_id;
  IF v_old_laptop_id IS NOT NULL AND v_new_laptop_id IS NOT NULL AND v_old_laptop_id <> v_new_laptop_id THEN
    IF v_old_laptop_id < v_new_laptop_id THEN
      PERFORM pg_advisory_xact_lock(v_old_laptop_id);
      PERFORM pg_advisory_xact_lock(v_new_laptop_id);
    ELSE
      PERFORM pg_advisory_xact_lock(v_new_laptop_id);
      PERFORM pg_advisory_xact_lock(v_old_laptop_id);
    END IF;
  ELSIF v_old_laptop_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(v_old_laptop_id);
  ELSIF v_new_laptop_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(v_new_laptop_id);
  END IF;

  IF v_old_laptop_id IS NOT NULL THEN
    SELECT * INTO v_old_laptop FROM laptops WHERE id = v_old_laptop_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Laptop % does not exist', v_old_laptop_id; END IF;
  END IF;
  IF v_new_laptop_id IS NOT NULL AND v_new_laptop_id <> v_old_laptop_id THEN
    SELECT * INTO v_laptop FROM laptops WHERE id = v_new_laptop_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Laptop % does not exist', v_new_laptop_id; END IF;
  END IF;

  UPDATE orders SET
    created_date = v_next.created_date,
    sale_online = v_next.sale_online,
    sale_offline = v_next.sale_offline,
    note = v_next.note,
    order_type = v_next.order_type,
    order_status = v_next.order_status,
    payment_status = v_next.payment_status,
    payment_method = v_next.payment_method,
    delivery_status = v_next.delivery_status,
    shipping_method = v_next.shipping_method,
    laptop_id = v_next.laptop_id,
    sale_price = v_next.sale_price,
    deposit_amount = v_next.deposit_amount,
    deposit_note = v_next.deposit_note,
    cod_amount = v_next.cod_amount,
    amount_paid = v_next.amount_paid,
    debt_amount = v_next.debt_amount,
    credit_card_fee = v_next.credit_card_fee,
    profit_vnd = v_next.profit_vnd,
    trade_in_laptop_id = v_next.trade_in_laptop_id,
    customer_id = v_next.customer_id,
    customer_info = v_next.customer_info,
    customer_address = v_next.customer_address,
    tracking_code = v_next.tracking_code,
    ship_date = v_next.ship_date,
    setup_note = v_next.setup_note,
    warranty = v_next.warranty,
    laptop_locked = v_next.laptop_locked,
    reservation_expires_at = v_next.reservation_expires_at,
    cancel_reason = v_next.cancel_reason,
    cancelled_at = v_next.cancelled_at,
    returned_at = v_next.returned_at,
    return_reason = v_next.return_reason,
    is_active = v_next.is_active,
    month_key = v_next.month_key,
    updated_at = v_next.updated_at
  WHERE id = v_order_id
  RETURNING * INTO v_order;

  IF v_old_laptop_id IS NOT NULL AND (v_new_laptop_id IS NULL OR v_new_laptop_id <> v_old_laptop_id) THEN
    v_previous_laptop := public.refresh_laptop_inventory(v_old_laptop_id);
  END IF;
  IF v_new_laptop_id IS NOT NULL THEN
    v_laptop := public.refresh_laptop_inventory(v_new_laptop_id);
  END IF;

  IF v_old_laptop_id IS NOT NULL AND (v_new_laptop_id IS NULL OR v_new_laptop_id <> v_old_laptop_id) THEN
    INSERT INTO stock_movements (laptop_id, order_id, movement_type, note, performed_by)
    VALUES (v_old_laptop_id, v_order.id, 'UNRESERVED', 'Laptop unlinked from order', p_recorded_by);
  END IF;
  IF v_new_laptop_id IS NOT NULL AND v_new_laptop_id <> v_old_laptop_id THEN
    INSERT INTO stock_movements (laptop_id, order_id, movement_type, note, performed_by)
    VALUES (
      v_new_laptop_id, v_order.id,
      CASE WHEN v_order.order_status IN ('prepared', 'shipping', 'done') THEN 'SOLD' ELSE 'RESERVED' END,
      'Laptop linked to order', p_recorded_by
    );
  END IF;

  RETURN jsonb_build_object(
    'order', to_jsonb(v_order),
    'laptop', CASE WHEN v_laptop.id IS NULL THEN NULL ELSE to_jsonb(v_laptop) END,
    'payments', '[]'::jsonb,
    'inventory_applied', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_repair_job(p_id uuid, p_data jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE j repair_jobs%ROWTYPE; assignee uuid:=nullif(p_data->>'assigned_to','')::uuid; target text:=coalesce(p_data->>'status','');
BEGIN
 SELECT * INTO j FROM repair_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR j.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Phiếu sửa không còn được cập nhật'; END IF;
 PERFORM validate_repair_assignee(assignee);
 IF NOT ((j.status='OPEN' AND target IN('OPEN','IN_PROGRESS')) OR
         (j.status='IN_PROGRESS' AND target IN('IN_PROGRESS','WAITING_PART','TESTING')) OR
         (j.status='WAITING_PART' AND target IN('WAITING_PART','IN_PROGRESS')) OR
         (j.status='TESTING' AND target IN('TESTING','IN_PROGRESS','WAITING_PART'))) THEN
   RAISE EXCEPTION 'Chuyển trạng thái sửa chữa không hợp lệ (% → %)',j.status,target;
 END IF;
 UPDATE repair_jobs SET
   reported_issue=left(coalesce(nullif(btrim(p_data->>'reported_issue'),''),reported_issue),5000),
   status=target,diagnosis=left(coalesce(p_data->>'diagnosis',''),5000),repair_plan=left(coalesce(p_data->>'repair_plan',''),5000),
   priority=coalesce(p_data->>'priority',priority),assigned_to=assignee,
   labor_cost_vnd=coalesce((p_data->>'labor_cost_vnd')::numeric,labor_cost_vnd),notes=left(coalesce(p_data->>'notes',''),5000),
   started_at=CASE WHEN target<>'OPEN' THEN coalesce(started_at,timezone('utc',now())) ELSE started_at END
 WHERE id=p_id RETURNING * INTO j;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'UPDATE',jsonb_build_object('status',j.status,'priority',j.priority,'assigned_to',j.assigned_to,'labor_cost_vnd',j.labor_cost_vnd),p_actor);
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION public.validate_product_qc_details()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE entry record; health numeric;
BEGIN
 IF jsonb_typeof(NEW.qc_details) IS DISTINCT FROM 'object' OR octet_length(NEW.qc_details::text)>50000 THEN
   RAISE EXCEPTION 'Chi tiết QC không hợp lệ'; END IF;
 FOR entry IN SELECT * FROM jsonb_each(NEW.qc_details) LOOP
   IF entry.key='batteryHealth' THEN
     IF entry.value<>'null'::jsonb AND entry.value<>'""'::jsonb THEN
       IF jsonb_typeof(entry.value) NOT IN ('number','string') OR (entry.value#>>'{}') !~ '^\d{1,3}$' THEN RAISE EXCEPTION 'Pin phải là số'; END IF;
       health:=(entry.value#>>'{}')::numeric;
       IF health<0 OR health>100 OR health<>trunc(health) THEN RAISE EXCEPTION 'Pin phải từ 0 đến 100'; END IF;
     END IF;
   ELSIF entry.key='serialNumber' THEN
     IF jsonb_typeof(entry.value)<>'string' OR length(btrim(entry.value#>>'{}'))>100 THEN RAISE EXCEPTION 'Serial không hợp lệ'; END IF;
   ELSIF entry.key='cosmeticGrade' THEN
     IF entry.value#>>'{}' NOT IN ('','A','B','C','D') OR jsonb_typeof(entry.value)<>'string' THEN RAISE EXCEPTION 'Ngoại hình không hợp lệ'; END IF;
   ELSE
     IF entry.key NOT IN ('serial','model','cpu','gpu','ram','ssd','mainboard','screen','keyboard','keyboard_backlight','touchpad','camera','microphone','speaker','wifi','bluetooth','usb','usb_c','hdmi','lan','battery','ssd_health','fan','cooling','cpu_stress','gpu_stress','charger','exterior')
       OR jsonb_typeof(entry.value)<>'object'
       OR coalesce(entry.value->>'result','') NOT IN ('NOT_TESTED','PASS','FAIL','WARNING','NOT_APPLICABLE')
       OR length(coalesce(entry.value->>'note',''))>1000 THEN RAISE EXCEPTION 'Mục QC không hợp lệ: %',entry.key; END IF;
   END IF;
 END LOOP;
 IF NEW.qc_details ? 'batteryHealth' THEN NEW.battery_health:=nullif(NEW.qc_details->>'batteryHealth','')::integer; END IF;
 IF NEW.qc_details ? 'serialNumber' AND btrim(NEW.qc_details->>'serialNumber')<>'' THEN NEW.serial:=btrim(NEW.qc_details->>'serialNumber'); END IF;
 IF NEW.qc_details ? 'screen' THEN NEW.screen_status:=CASE NEW.qc_details#>>'{screen,result}' WHEN 'PASS' THEN 'ok' WHEN 'FAIL' THEN 'error' WHEN 'WARNING' THEN 'error' ELSE NULL END; END IF;
 IF NEW.qc_details ? 'mainboard' THEN NEW.mainboard_status:=CASE NEW.qc_details#>>'{mainboard,result}' WHEN 'PASS' THEN 'ok' WHEN 'FAIL' THEN 'error' WHEN 'WARNING' THEN 'error' ELSE NULL END; END IF;
 IF NEW.qc_details ? 'camera' OR NEW.qc_details ? 'microphone' THEN
   NEW.camera_mic_status:=CASE WHEN NEW.qc_details#>>'{camera,result}' IN ('FAIL','WARNING') OR NEW.qc_details#>>'{microphone,result}' IN ('FAIL','WARNING') THEN 'error'
     WHEN NEW.qc_details#>>'{camera,result}'='PASS' AND NEW.qc_details#>>'{microphone,result}'='PASS' THEN 'ok' ELSE NULL END;
 END IF;
 NEW.qc_details:=NEW.qc_details-'serialNumber'-'batteryHealth';
 RETURN NEW;
END $function$
